@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-7-home-7 (CTA — Ready to Build the Future?)
/*----------------------------------------*/

.sec-7-home-7 {
    position: relative;
    background: #7f0b01;
    color: #fefefe;

    &__media {
        width: 100%;
        max-width: 798px;
        aspect-ratio: 1 / 1;
        overflow: hidden;

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }
    }

    &__eyebrow {
        color: #fefefe;
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;
    }

    &__headline {
        font-family: var(--at-heading-font);
        font-size: 48px;
        font-weight: 600;
        line-height: 52px;
        letter-spacing: -0.05em;
        color: #fefefe;
        max-width: 650px;

        @media #{$lg,$md} {
            font-size: 40px;
            line-height: 1.15;
        }

        @media #{$sm,$xs} {
            font-size: 32px;
            line-height: 1.2;
        }
    }

    &__features {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 16px 39px;
        max-width: 560px;

        @media #{$sm,$xs} {
            grid-template-columns: 1fr;
            gap: 14px;
        }
    }

    &__feature {
        display: flex;
        align-items: center;
        gap: 12px;
        font-size: 16px;
        font-weight: 500;
        letter-spacing: -0.02em;
        color: #fefefe;
        margin: 0;
    }

    &__cta-btn {
        background: var(--at-theme-primary, #f0460e);
        border-radius: 50px 0 0 50px;
        padding-inline: 27px;
        min-height: 50px;
    }

    &__cta-circle {
        width: 50px;
        min-width: 50px;
        height: 50px;
        background: var(--at-theme-primary, #f0460e);
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: transform 0.35s ease, background 0.35s ease;

        &:hover {
            transform: translateY(-2px);
        }

        img {
            display: block;
        }
    }

    &__star {
        position: absolute;
        right: 100px;
        bottom: 120px;
        width: 100px;
        height: 100px;
        pointer-events: none;

        img {
            width: 100%;
            height: 100%;
            display: block;
            animation: sec7Home7Spin 12s linear infinite;
        }

        @media #{$lg,$md,$sm,$xs} {
            right: 24px;
            bottom: 24px;
            opacity: 0.9;
        }
    }
}

@keyframes sec7Home7Spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}