@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-3-home-9 (Home 9 — about + 3 pillars)
/*----------------------------------------*/

.sec-3-home-9 {
    position: relative;
    overflow: hidden;
    padding-top: clamp(60px, 6.5vw, 130px);
    padding-bottom: clamp(60px, 6.5vw, 130px);

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    // Left column: hero image
    &__visual {
        max-width: 699px;
    }

    &__hero-thumb {
        position: relative;
        width: 100%;
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-100);
        aspect-ratio: 699 / 415;

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    // Right column: intro
    &__intro {
        padding-top: 0;
        max-width: 872px;
        margin-left: auto;

        @media #{$lg} {
            padding-top: 0;
        }
    }

    &__eyebrow {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.3;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
        text-decoration: none;
        margin-bottom: 22px;
        transition: color 0.3s ease;

        &:hover {
            color: var(--at-theme-primary);
        }
    }

    &__eyebrow-icon {
        display: inline-flex;
        line-height: 0;

        img {
            display: block;
        }
    }

    &__headline {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(32px, 3.35vw, 64px);
        line-height: 1.125;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950);
        margin-bottom: 22px;
    }

    &__lede {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(16px, 1.05vw, 20px);
        line-height: 1.5;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
    }

    // Pillar list
    &__features {
        display: flex;
        flex-direction: column;
        gap: 32px;
        margin-top: 42px;
        max-width: 872px;
    }

    &__feature {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 30px;

        @media #{$xs} {
            flex-direction: column;
            align-items: flex-start;
        }
    }

    &__feature-thumb {
        position: relative;
        flex: 0 0 auto;
        width: 100%;
        max-width: 348px;
        height: 139px;
        border-radius: 8px;
        overflow: hidden;
        background: var(--at-neutral-100);

        @media #{$xs} {
            max-width: 100%;
        }

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    &__feature-text {
        flex: 1 1 0;
        min-width: 0;
        max-width: 448px;
    }

    &__feature-title {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(24px, 1.9vw, 36px);
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
        margin-bottom: 16px;
    }

    &__feature-desc {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.45;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900);
    }
}
