@use '../../utils' as *;

/* ===========================================================
   Section 4 — Home 14 (Gallery / Archive)
   =========================================================== */

.sec-4-home-14 {
    padding-top: 140px;
    padding-bottom: 140px;
    background-color: var(--at-neutral-0);
    border-top: 1px solid var(--at-neutral-200);

    @media #{$xxl},
    #{$xl} {
        padding-top: 100px;
        padding-bottom: 100px;
    }

    @media #{$lg},
    #{$md} {
        padding-top: 80px;
        padding-bottom: 80px;
    }

    @media #{$sm},
    #{$xs} {
        padding-top: 56px;
        padding-bottom: 56px;
    }

    &__inner {
        max-width: 1920px;
        margin: 0 auto;
        padding-left: 100px;
        padding-right: 100px;

        @media #{$x4l},
        #{$x3l},
        #{$xxl} {
            padding-left: 60px;
            padding-right: 60px;
        }

        @media #{$xl} {
            padding-left: 40px;
            padding-right: 40px;
        }

        @media #{$lg},
        #{$md} {
            padding-left: 30px;
            padding-right: 30px;
        }

        @media #{$sm},
        #{$xs} {
            padding-left: 16px;
            padding-right: 16px;
        }
    }

    /* Header */
    &__head {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        gap: 40px;
        margin-bottom: 48px;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            flex-direction: column;
            align-items: flex-start;
            gap: 28px;
        }
    }

    &__head-left {
        display: flex;
        flex-direction: column;
        gap: 20px;
    }

    &__head-right {
        display: flex;
        flex-direction: column;
        align-items: flex-end;
        gap: 16px;
        max-width: 380px;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            align-items: flex-start;
            max-width: none;
        }
    }

    &__head-copy {
        font-family: var(--at-ff-body);
        font-size: 14px;
        line-height: 1.6;
        color: var(--at-neutral-500);
        text-align: right;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            text-align: left;

            br {
                display: none;
            }
        }
    }

    &__eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        font-family: var(--at-ff-body);
        font-size: 11px;
        line-height: 1;
        text-transform: uppercase;
    }

    &__eyebrow-dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background-color: var(--at-neutral-950);
    }

    &__eyebrow-key {
        font-weight: 600;
        color: var(--at-neutral-950);
        letter-spacing: 2px;
    }

    &__eyebrow-meta {
        font-weight: 400;
        color: var(--at-neutral-500);
        letter-spacing: 1.2px;
    }

    &__title {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: clamp(40px, 5vw, 84px);
        line-height: 1;
        letter-spacing: -0.025em;
        color: var(--at-neutral-950);

        @media #{$xs} {
            br {
                display: none;
            }
        }
    }

    &__btn-primary {
        display: inline-flex;
        align-items: stretch;
        color: var(--at-neutral-0);
        text-decoration: none;
        transition: opacity 0.3s ease;

        .sec-4-home-14__btn-label {
            display: inline-flex;
            align-items: center;
            background: var(--at-neutral-900);
            color: var(--at-neutral-0);
            padding: 14px 27px;
            border-radius: 50px 0 0 50px;
            font-family: var(--at-ff-body);
            font-weight: 600;
            font-size: 16px;
            letter-spacing: -0.05em;
            line-height: 1;
            white-space: nowrap;
        }

        .sec-4-home-14__btn-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: var(--at-neutral-900);
            color: var(--at-neutral-0);
            width: 50px;
            height: 50px;
            border-radius: 50%;
            margin-left: 2px;
        }

        &:hover {
            opacity: 0.85;
            color: var(--at-neutral-0);
        }
    }

    /* Filter tabs */
    &__tabs {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        padding: 12px 0;
        border-top: 1px solid var(--at-neutral-200);
        border-bottom: 1px solid var(--at-neutral-200);
        margin-bottom: 48px;
    }

    &__tab {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 10px 18px;
        border: 1px solid var(--at-neutral-200);
        background: transparent;
        border-radius: 999px;
        cursor: pointer;
        font-family: var(--at-ff-body);
        line-height: 1;
        color: var(--at-neutral-950);
        transition: all 0.25s ease;

        &.is-active {
            background-color: var(--at-neutral-950);
            border-color: var(--at-neutral-950);
            color: var(--at-neutral-0);

            .sec-4-home-14__tab-count {
                color: var(--at-neutral-0);
                opacity: 0.7;
            }
        }

        &:hover:not(.is-active) {
            border-color: var(--at-neutral-950);
        }
    }

    &__tab-label {
        font-weight: 500;
        font-size: 13px;
    }

    &__tab-count {
        font-weight: 400;
        font-size: 11px;
        letter-spacing: 0.4px;
        color: var(--at-neutral-500);
    }

    /* Masonry */
    &__masonry {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 24px;
        margin-bottom: 48px;

        @media #{$md} {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        @media #{$sm},
        #{$xs} {
            grid-template-columns: 1fr;
            gap: 20px;
        }
    }

    &__col {
        display: flex;
        flex-direction: column;
        gap: 24px;

        &--offset-60 {
            padding-top: 60px;

            @media #{$md},
            #{$sm},
            #{$xs} {
                padding-top: 0;
            }
        }

        &--offset-30 {
            padding-top: 30px;

            @media #{$md},
            #{$sm},
            #{$xs} {
                padding-top: 0;
            }
        }
    }

    &__tile {
        position: relative;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        padding: 20px;
        border-radius: 4px;
        overflow: hidden;
        text-decoration: none;
        color: var(--at-common-white);
        background-color: var(--at-neutral-900);

        &--h420 {
            aspect-ratio: 557 / 420;
        }

        &--h440 {
            aspect-ratio: 557 / 440;
        }

        &--h480 {
            aspect-ratio: 557 / 480;
        }

        &--h500 {
            aspect-ratio: 557 / 500;
        }

        &--h520 {
            aspect-ratio: 557 / 520;
        }

        &--h540 {
            aspect-ratio: 557 / 540;
        }

        &--h560 {
            aspect-ratio: 557 / 560;
        }

        &--h600 {
            aspect-ratio: 557 / 600;
        }

        &--h620 {
            aspect-ratio: 557 / 620;
        }

        &--h700 {
            aspect-ratio: 557 / 700;
        }

        &--h720 {
            aspect-ratio: 557 / 720;
        }

        @media #{$sm},
        #{$xs} {
            aspect-ratio: 4 / 5 !important;
        }

        &:hover {
            color: var(--at-common-white);

            .sec-4-home-14__tile-img {
                transform: scale(1.08) rotate(-1.2deg);
                filter: saturate(1.12) contrast(1.04);
            }
        }
    }

    &__tile-img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        pointer-events: none;
        border-radius: 4px;
        transform-origin: center;
        transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
            filter 0.6s ease;
    }

    &__tile-top {
        position: relative;
        z-index: 2;
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        gap: 16px;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 10px;
        color: #fff;
        opacity: 0.6;
    }

    &__tile-num {
        letter-spacing: 2px;
    }

    &__tile-year {
        letter-spacing: 0.4px;
    }

    &__tile-meta {
        position: relative;
        z-index: 2;
        display: flex;
        flex-direction: column;
        gap: 4px;
        font-family: var(--at-ff-body);
        color: #fff;
    }

    &__tile-title {
        font-weight: 500;
        font-size: 18px;
        letter-spacing: -0.3px;
        line-height: 1.1;
    }

    &__tile-sub {
        font-weight: 400;
        font-size: 11px;
        letter-spacing: 0.4px;
        opacity: 0.7;
    }

    /* Bottom row */
    &__bottom {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 24px;

        @media #{$sm},
        #{$xs} {
            flex-direction: column;
            align-items: flex-start;
        }
    }

    &__bottom-text {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 11px;
        letter-spacing: 2px;
        color: var(--at-neutral-500);
    }
}