@use '../../utils' as *;

/* Home 13 / Section 3 — Selected Projects */
.sec-3-home-13 {
    background-color: var(--at-neutral-50);
    padding: 120px 96px;
}

.sec-3-home-13__inner {
    display: flex;
    flex-direction: column;
    gap: 80px;
}

/* ── Header ──────────────────────────────────── */
.sec-3-home-13__header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 32px;
}

.sec-3-home-13__head-text {
    display: flex;
    flex-direction: column;
    gap: 32px;
}

.sec-3-home-13__label {
    display: inline-flex;
    align-items: center;
    gap: 12px;
}

.sec-3-home-13__label-dot {
    width: 8px;
    height: 8px;
    background-color: var(--at-theme-primary);
    flex-shrink: 0;
}

.sec-3-home-13__label-text {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 13px;
    line-height: 1;
    letter-spacing: 0.08em;
    color: var(--at-neutral-700);
}

.sec-3-home-13__title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(36px, 4.4vw, 64px);
    line-height: 1.125;
    letter-spacing: -0.03em;
    color: var(--at-neutral-950);
    max-width: 100%;
}

.sec-3-home-13__title-italic {
    display: block;
    font-style: italic;
}

.sec-3-home-13__cta {
    display: inline-flex;
    align-items: center;
    gap: 0;
    text-decoration: none;
    transition: opacity 0.3s ease;

    &:hover,
    &:focus-visible {
        opacity: 0.9;
    }

    &:hover .sec-3-home-13__cta-icon svg,
    &:focus-visible .sec-3-home-13__cta-icon svg {
        transform: translate(2px, -2px);
    }
}

.sec-3-home-13__cta-label {
    display: inline-flex;
    align-items: center;
    height: 50px;
    padding: 14px 27px;
    background-color: var(--at-neutral-900);
    color: var(--at-neutral-0);
    border-radius: 50px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    letter-spacing: -0.05em;
    white-space: nowrap;
}

.sec-3-home-13__cta-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    background-color: var(--at-neutral-900);
    color: var(--at-neutral-0);
    border-radius: 50%;
    margin-left: -1px;

    svg {
        transition: transform 0.3s ease;
    }
}

/* ── Project list ────────────────────────────── */
.sec-3-home-13__list {
    display: flex;
    flex-direction: column;
}

.sec-3-home-13__card {
    display: grid;
    grid-template-columns: 360px 680px 1fr;
    gap: 48px;
    padding: 40px 8px;
    border-top: 1px solid var(--at-neutral-100);
    align-items: start;

    &:last-child {
        border-bottom: 1px solid var(--at-neutral-100);
    }
}

/* ── Card meta (left) ────────────────────────── */
.sec-3-home-13__card-meta {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    padding: 12px 0;
}

.sec-3-home-13__card-loc {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.08em;
    color: var(--at-neutral-500);
    white-space: nowrap;
}

.sec-3-home-13__card-title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 32px;
    line-height: 1.1875;
    letter-spacing: -0.03em;
    color: var(--at-neutral-950);
}

.sec-3-home-13__card-link {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.08em;
    color: var(--at-neutral-950);
    text-decoration: none;
    transition: color 0.3s ease;

    &:hover,
    &:focus-visible {
        color: var(--at-theme-primary);
    }
}

.sec-3-home-13__card-link-dots {
    color: var(--at-neutral-500);
    font-size: 11px;
    letter-spacing: 0.08em;
    line-height: 1;
}

/* ── Card media (middle) ─────────────────────── */
.sec-3-home-13__card-media {
    display: block;
    width: 100%;
    overflow: hidden;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform 0.6s ease;
    }

    &:hover img,
    &:focus-visible img {
        transform: scale(1.04);
    }
}

/* ── Card info (right) ───────────────────────── */
.sec-3-home-13__card-info {
    display: flex;
    flex-direction: column;
    gap: 24px;
    padding-top: 12px;
    min-width: 0;
}

.sec-3-home-13__card-desc {
    font-family: var(--at-ff-body);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.5;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
}

.sec-3-home-13__card-specs {
    display: flex;
    flex-direction: column;
    margin: 0;
}

.sec-3-home-13__card-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 0;
    border-bottom: 1px solid var(--at-neutral-100);
    gap: 16px;

    &:first-child {
        border-top: 1px solid transparent;
    }

    &:last-child {
        border-bottom: none;
    }

    dt {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 12px;
        line-height: 1;
        letter-spacing: 0.08em;
        color: var(--at-neutral-500);
        margin: 0;
    }

    dd {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.02em;
        color: var(--at-neutral-950);
        margin: 0;
        text-align: right;
    }
}

/* ── Responsive ──────────────────────────────── */
@media #{$xxl} {
    .sec-3-home-13 {
        padding: 96px 32px;
    }

    .sec-3-home-13__card {
        grid-template-columns: 280px 540px 1fr;
        gap: 32px;
    }

    .sec-3-home-13__card-media,
    .sec-3-home-13__card-meta {
        height: 380px;
    }
}

@media #{$xl} {
    .sec-3-home-13 {
        padding: 80px 24px;
    }

    .sec-3-home-13__inner {
        gap: 56px;
    }

    .sec-3-home-13__card {
        grid-template-columns: 240px 420px 1fr;
        gap: 24px;
        padding: 32px 0;
    }

    .sec-3-home-13__card-media,
    .sec-3-home-13__card-meta {
        height: 320px;
    }

    .sec-3-home-13__card-title {
        font-size: 26px;
    }
}

@media #{$lg} {
    .sec-3-home-13 {
        padding: 64px 20px;
    }

    .sec-3-home-13__header {
        flex-direction: column;
        align-items: flex-start;
        gap: 24px;
    }

    .sec-3-home-13__card {
        grid-template-columns: 1fr 1fr;
        grid-template-areas:
            "media media"
            "meta info";
        gap: 24px;
        padding: 32px 0;
    }

    .sec-3-home-13__card-media {
        grid-area: media;
        height: 340px;
    }

    .sec-3-home-13__card-meta {
        grid-area: meta;
        height: auto;
        gap: 16px;
        justify-content: flex-start;
    }

    .sec-3-home-13__card-info {
        grid-area: info;
    }
}

@media #{$md} {
    .sec-3-home-13 {
        padding: 48px 30px;
    }

    .sec-3-home-13__inner {
        gap: 40px;
    }

    .sec-3-home-13__card {
        grid-template-columns: 1fr;
        grid-template-areas:
            "media"
            "meta"
            "info";
        gap: 20px;
        padding: 24px 0;
    }

    .sec-3-home-13__card-media {
        height: 280px;
    }
}

@media #{$sm} {
    .sec-3-home-13 {
        padding: 36px 30px;
    }

    .sec-3-home-13__cta-label {
        padding: 14px 20px;
    }

    .sec-3-home-13__card-media {
        height: 240px;
    }
}

@media #{$xs} {
    .sec-3-home-13 {
        padding: 36px 30px;
    }

    .sec-3-home-13__card-title {
        font-size: 22px;
    }

    .sec-3-home-13__card-row dd {
        font-size: 14px;
    }
}

/* Cascading mobile pivot: stack header for tablet & phone */
@media (max-width: 1199.98px) {
    .sec-3-home-13__header {
        flex-direction: column;
        align-items: flex-start;
        gap: 24px;
    }
}

/* Cascading mobile pivot: single-column card layout for phone */
@media (max-width: 767.98px) {
    .sec-3-home-13__card {
        grid-template-columns: 1fr;
        grid-template-areas:
            "media"
            "meta"
            "info";
        gap: 20px;
        padding: 24px 0;
    }

    .sec-3-home-13__card-media {
        grid-area: media;
        height: auto;
    }

    .sec-3-home-13__card-meta {
        grid-area: meta;
        height: auto;
        gap: 16px;
        justify-content: flex-start;
    }

    .sec-3-home-13__card-info {
        grid-area: info;
    }
}