/* Portfolio - Horizontal Scroll Gallery
   ---------------------------------------------------------------
   Two scoped wrappers:
     .hsg-intro  - normal-flow lead-in section above the gallery
     .hsg-stage  - the pinned section driven by GSAP ScrollTrigger
                   (see assets/js/horizontal-scroll-gallery.js)

   Everything is namespaced under .hsg- to avoid clashing with the
   other slideshow variants in _slideshow.scss.
*/

/* =====================================================================
   INTRO - lead-in section before the pin
   ===================================================================== */
.hsg-intro {
   position: relative;
   min-height: 70svh;
   display: flex;
   align-items: center;
   padding: 8rem 0 6rem;
   background-color: var(--at-neutral-50);
   color: var(--at-neutral-950);
   overflow: hidden;

   .hsg-intro__eyebrow {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.3em;
      text-transform: uppercase;
      padding-bottom: 0.5rem;
      border-bottom: 1px solid currentColor;
      opacity: 0.75;
      margin-bottom: 1.75rem;
   }

   .hsg-intro__title {
      font-size: clamp(2.5rem, 7vw, 6rem);
      line-height: 0.95;
      font-weight: 600;
      letter-spacing: -0.03em;
      text-transform: uppercase;
      max-width: 16ch;
      margin: 0 0 1.5rem;
   }

   .hsg-intro__desc {
      font-size: clamp(1rem, 1.2vw, 1.15rem);
      line-height: 1.55;
      max-width: 56ch;
      opacity: 0.8;
      margin: 0 0 3rem;
   }

   .hsg-intro__hint {
      display: inline-flex;
      align-items: center;
      gap: 1rem;
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.3em;
      text-transform: uppercase;
      opacity: 0.7;
   }

   .hsg-intro__hint-line {
      display: block;
      width: 80px;
      height: 1px;
      background-color: currentColor;
      animation: hsgHintPulse 2.4s ease-in-out infinite;
   }

   @media (max-width: 991px) {
      min-height: 60svh;
      padding: 6rem 0 4rem;
   }

   @media (max-width: 575px) {
      min-height: 55svh;
      padding: 5rem 0 3rem;

      .hsg-intro__hint-line {
         width: 56px;
      }
   }
}

@keyframes hsgHintPulse {

   0%,
   100% {
      opacity: 0.35;
      transform: translateX(0);
   }

   50% {
      opacity: 1;
      transform: translateX(8px);
   }
}

/* =====================================================================
   STAGE - the pinned horizontal scroll section
   ===================================================================== */
.hsg-stage {
   position: relative;
   width: 100%;
   height: 100svh;
   overflow: hidden;
   color: #fefefe;
   background-color: var(--at-neutral-950);

   * {
      box-sizing: border-box;
   }

   /* -------------------- Background layer -------------------- */
   .hsg-bg-layer {
      position: absolute;
      inset: 0;
      z-index: 0;
   }

   .hsg-bg {
      position: absolute;
      inset: 0;
      opacity: 0;
      transform: scale(1.12);
      transition: opacity 0.8s ease, transform 6s ease-out;
      will-change: opacity, transform;
   }

   /* Ken-Burns-style slow drift on the active background — the longer the
      user lingers on a slide, the more the image breathes. */
   .hsg-bg.is-active {
      opacity: 1;
      transform: scale(1) translateX(-1%);
   }

   .hsg-bg__img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      display: block;
      filter: brightness(0.7) saturate(0.9);
   }

   /* Tint veil on top of all backgrounds to lift card contrast. */
   .hsg-bg__veil {
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg,
            rgba(0, 0, 0, 0.25) 0%,
            rgba(0, 0, 0, 0.35) 60%,
            rgba(0, 0, 0, 0.6) 100%);
      backdrop-filter: blur(2px);
      -webkit-backdrop-filter: blur(2px);
      pointer-events: none;
   }

   /* -------------------- Track of cards -------------------- */
   .hsg-track-wrap {
      position: relative;
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      overflow: hidden;
      z-index: 1;
   }

   .hsg-track {
      display: flex;
      align-items: center;
      will-change: transform;
      /* Side padding (centers the first/last slide) and inter-slide gap
         (margin-left: 50svw) are applied by horizontal-scroll-gallery.js so
         the spacing rule lives next to the scroll logic that depends on it. */
   }

   /* -------------------- Slide card --------------------
      Vertical layout: media on top (~40%), body fills the rest with
      a solid black panel that holds title + tags. */
   .hsg-slide {
      /* Hover palette — kept as CSS vars so a future per-slide accent
         (e.g. data-accent) could override just these three values. */
      --hsg-hover-bg: #212121;
      --hsg-hover-fg: #fefefe;
      --hsg-hover-border: #212121;

      flex: 0 0 auto;
      width: 36vw;
      max-width: 520px;
      min-width: 320px;
      height: 76vh;
      max-height: 760px;
      position: relative;
      background-color: #0F0F0F;
      /* Transparent border by default so hover doesn't reflow the layout. */
      border: 5px solid transparent;

      /* Exit pose driven by --hsg-exit (set by JS to the slide's segment
         progress, 0..1). When this card becomes active and the user keeps
         scrolling, exit ramps from 0 to 1 across its segment:
           - translate X right by up to 80px
           - scale down to 0.65
         Once past its segment the slide holds the exit pose; the track
         then carries it offscreen-left so the reset is never visible.

         translate/scale have NO transition so the motion stays tight to
         scroll. Hover/active color swaps still transition. */
      translate: calc(var(--hsg-exit, 0) * 80px) 0;
      scale: calc(1 - var(--hsg-exit, 0) * 0.35);
      transition:
         box-shadow 0.6s ease,
         background-color 0.4s ease,
         border-color 0.4s ease;
      box-shadow: 0 30px 80px rgba(0, 0, 0, 0.35);
   }

   .hsg-slide.is-active {
      box-shadow: 0 40px 120px rgba(0, 0, 0, 0.55);
   }

   /* Hover / keyboard-focus state — swap to the accent palette and
      reveal the border. :focus-within picks up keyboard users on the
      inner <a>. Parallax dim on the body is also neutralized so the
      card feels "lit up" regardless of where it sits on the track. */
   .hsg-slide:hover,
   .hsg-slide:focus-within {
      background-color: var(--hsg-hover-bg);
      border-color: var(--hsg-hover-border);
   }

   .hsg-slide__link {
      position: relative;
      display: flex;
      flex-direction: column;
      width: 100%;
      height: 100%;
      color: inherit;
      text-decoration: none;
      overflow: hidden;
      isolation: isolate;
   }

   .hsg-slide__media {
      /* Height is driven by the image's fixed 2400:1600 (3:2) aspect ratio
         (set on .hsg-slide__img), not by a flex basis. Because all slides
         share the same width at any given breakpoint, all thumbnails end up
         the same height across cards. */
      position: relative;
      flex: 0 0 auto;
      width: 100%;
      overflow: hidden;
   }

   /* The image is intentionally over-scaled so the parallax translateX never
      reveals an empty edge inside the frame. `scale` and `translate` are set
      as individual transform properties so we can transition them separately:
      scale animates over 1.2s on .is-active, translate updates instantly to
      follow the scroll-driven --hsg-norm value. */
   .hsg-slide__img {
      width: 100%;
      height: auto;
      aspect-ratio: 2400 / 1600;
      object-fit: cover;
      display: block;
      scale: 1.18;
      translate: calc(var(--hsg-norm, 0) * -14%) 0;
      transition: scale 1.2s ease;
      will-change: transform;
   }

   .hsg-slide.is-active .hsg-slide__img {
      scale: 1.04;
   }

   .hsg-slide__body {
      flex: 1 1 auto;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 2.25rem 2rem 2rem;
      background-color: #0F0F0F;
      color: #fefefe;
      min-height: 0;
      /* Centered cards are fully opaque; off-center cards dim toward 0.45.
         This complements the binary .is-active state with a smooth fade. */
      opacity: calc(0.45 + var(--hsg-centeredness, 1) * 0.55);
      transition:
         background-color 0.4s ease,
         color 0.4s ease,
         opacity 0.35s ease;
   }

   .hsg-slide:hover .hsg-slide__body,
   .hsg-slide:focus-within .hsg-slide__body {
      background-color: var(--hsg-hover-bg);
      color: var(--hsg-hover-fg);
      opacity: 1;
   }

   .hsg-slide__title {
      margin: 0;
      letter-spacing: -0.02em;
      color: #fefefe;
      overflow-wrap: break-word;
      translate: 0 calc(var(--hsg-norm, 0) * -10px);
      transition: color 0.4s ease;
   }

   .hsg-slide:hover .hsg-slide__title,
   .hsg-slide:focus-within .hsg-slide__title {
      color: var(--hsg-hover-fg);
   }

   .hsg-slide__tags {
      margin: 0;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.65rem;
      font-size: 0.85rem;
      font-weight: 500;
      letter-spacing: 0.02em;
      color: rgba(255, 255, 255, 0.9);
      /* Slight opposite-direction drift to the image — image translates left,
         tags drift right (and vice versa). Small magnitude keeps it subtle. */
      translate: calc(var(--hsg-norm, 0) * 6px) 0;
      transition: color 0.4s ease;
   }

   .hsg-slide:hover .hsg-slide__tags,
   .hsg-slide:focus-within .hsg-slide__tags {
      color: #fefefe;
   }

   .hsg-slide__tag-sep {
      display: inline-block;
      color: rgba(255, 255, 255, 0.35);
      font-weight: 400;
      transform: translateY(-1px);
      transition: color 0.4s ease;
   }

   .hsg-slide:hover .hsg-slide__tag-sep,
   .hsg-slide:focus-within .hsg-slide__tag-sep {
      color: rgba(0, 0, 0, 0.35);
   }

   /* -------------------- Progress bar -------------------- */
   .hsg-progress {
      position: absolute;
      left: 50%;
      bottom: 2.5rem;
      transform: translateX(-50%);
      width: clamp(180px, 28vw, 360px);
      height: 2px;
      background-color: rgba(255, 255, 255, 0.2);
      z-index: 4;
      overflow: hidden;
   }

   .hsg-progress__bar {
      display: block;
      width: 100%;
      height: 100%;
      background-color: #fefefe;
      transform-origin: 0 50%;
      transform: scaleX(0);
      transition: transform 0.08s linear;
   }

   /* -------------------- Counter --------------------
      Centered horizontally and parked 30px above the progress bar.
      The bottom offset is `progress.bottom + progress.height + 30px`,
      so keep the responsive overrides in lock-step with .hsg-progress. */
   .hsg-counter {
      position: absolute;
      left: 50%;
      bottom: calc(2.5rem + 2px + 30px);
      transform: translateX(-50%);
      display: inline-flex;
      align-items: baseline;
      gap: 0.35rem;
      font-size: 0.85rem;
      font-weight: 600;
      letter-spacing: 0.25em;
      color: #fefefe;
      z-index: 4;
   }

   .hsg-counter__current {
      font-size: 1.5rem;
      line-height: 1;
   }

   .hsg-counter__sep,
   .hsg-counter__total {
      opacity: 0.6;
   }

   /* -------------------- Responsive -------------------- */
   @media (max-width: 991px) {
      .hsg-slide {
         width: 56vw;
         height: 70vh;
         min-width: 280px;
      }

      .hsg-slide__body {
         padding: 1.75rem 1.5rem 1.5rem;
      }

      .hsg-counter {
         bottom: calc(1.75rem + 2px + 30px);
      }

      .hsg-progress {
         bottom: 1.75rem;
      }
   }

   @media (max-width: 575px) {
      .hsg-slide {
         width: 78vw;
         height: 64vh;
         max-height: 560px;
         min-width: 0;
      }

      .hsg-slide__body {
         padding: 1.5rem 1.25rem 1.25rem;
      }

      .hsg-slide__title {
         font-size: clamp(1rem, 4.5vw, 1.5rem);
         max-width: 6ch;
      }

      .hsg-slide__tags {
         font-size: 0.75rem;
         gap: 0.5rem;
      }

      .hsg-progress {
         bottom: 1.25rem;
         width: 50vw;
      }

      .hsg-counter {
         bottom: calc(1.25rem + 2px + 30px);
         font-size: 0.7rem;
      }

      .hsg-counter__current {
         font-size: 1.15rem;
      }
   }

   /* Respect users who prefer reduced motion - keep layout, drop the
      decorative parallax. ScrollTrigger still drives the track. */
   @media (prefers-reduced-motion: reduce) {

      .hsg-bg,
      .hsg-slide,
      .hsg-slide__img,
      .hsg-slide__title,
      .hsg-slide__tags,
      .hsg-slide__body {
         transition: none;
      }

      .hsg-bg {
         transform: none;
      }

      .hsg-slide {
         translate: 0 0;
         scale: 1;
      }

      .hsg-slide__img {
         scale: 1;
         translate: 0 0;
      }

      .hsg-slide__title,
      .hsg-slide__tags {
         translate: 0 0;
      }

      .hsg-slide__body {
         opacity: 1;
      }
   }
}