@use '../../utils' as *;

/*----------------------------------------*/
/*  Portfolio Details 4 — Sticky Sidebar + Chapters
/*  Brand accent: var(--at-theme-primary) (#F0460E)
/*----------------------------------------*/

/* JS injects `.anim-zoomin-wrap` around every `.anim-zoomin` <img>.
   Image hosts use absolute-fill img inside aspect-ratio box. */
.sec-2-portfolio-details-4__inline-fig,
.sec-4-portfolio-details-4__cell,
.sec-5-portfolio-details-4__media {
    .anim-zoomin-wrap {
        position: absolute;
        inset: 0;
        overflow: hidden;
    }
}

/* =========================================================
   SEC 1 — Compact title block
   ========================================================= */
.sec-1-portfolio-details-4 {
    background-color: var(--at-neutral-0);

    &__crumbs {
        letter-spacing: 0.1em;

        span {
            margin: 0 8px;
            color: var(--at-neutral-300);
        }
    }

    &__title {
        letter-spacing: -0.05em;

        sup {
            margin-left: 4px;
            line-height: 1;
        }
    }

    &__tagline {
        letter-spacing: -0.03em;
        line-height: 1.35;
    }

    &__tags {
        gap: 8px;
    }

    &__tag {
        padding: 8px 18px;
        background: var(--at-neutral-50);
        color: var(--at-neutral-900);
        border-radius: 25px;
        letter-spacing: 0.05em;
    }

    &__demo {
        text-decoration: none;
        display: inline-flex;
        align-items: center;
        gap: 8px;
        transition: gap 0.3s ease;

        span {
            transition: transform 0.3s ease;
        }

        &:hover {
            color: var(--at-theme-primary);
            gap: 12px;

            span {
                transform: translate(3px, -3px);
            }
        }
    }

    @media #{$md} {
        padding-top: 100px;
        padding-bottom: 40px;
    }

    @media #{$sm,$xs} {
        padding-top: 90px;
        padding-bottom: 30px;

        &__title {
            margin-bottom: 18px !important;
        }

        &__tagline {
            margin-bottom: 30px;
        }

        &__crumbs span {
            margin: 0 6px;
        }
    }

    @media #{$xs} {
        &__title {
            font-size: 54px !important;
        }
    }
}

/* =========================================================
   SEC 2 — Sticky sidebar + chapters
   ========================================================= */
.sec-2-portfolio-details-4 {
    background-color: var(--at-neutral-0);

    &__sidebar-col {
        position: relative;
    }

    &__sidebar {
        position: sticky;
        top: 120px;
        background: var(--at-neutral-50);
        border-radius: 8px;
        padding: 32px;
    }

    &__sidebar-eyebrow {
        letter-spacing: 0.1em;
        margin-bottom: 16px;
    }

    &__meta {
        padding-top: 0;
    }

    &__meta-row {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        gap: 16px;
        padding: 14px 0;
        border-top: 1px solid var(--at-neutral-100);

        dt {
            margin: 0;
            flex-shrink: 0;
        }

        dd {
            text-align: right;
            letter-spacing: -0.02em;
        }

        &:last-child {
            border-bottom: 1px solid var(--at-neutral-100);
        }
    }

    &__services {
        li {
            padding: 6px 0;
            color: var(--at-neutral-900);
            font-size: var(--at-fz-font-md);
            letter-spacing: -0.02em;

            &::before {
                content: '— ';
                color: var(--at-theme-primary);
                margin-right: 4px;
            }
        }
    }

    &__cta {
        padding: 14px 22px;
        background: var(--at-neutral-950);
        color: var(--at-neutral-0);
        border-radius: 23px;
        text-decoration: none;
        transition: background-color 0.3s ease, transform 0.3s ease;

        span {
            transition: transform 0.3s ease;
        }

        &:hover {
            background: var(--at-theme-primary);
            color: var(--at-neutral-0);
            transform: translateY(-2px);

            span {
                transform: translate(3px, -3px);
            }
        }
    }

    &__content-col {
        padding-left: 60px;
    }

    &__chapter {
        padding-bottom: 70px;
        margin-bottom: 70px;
        border-bottom: 1px solid var(--at-neutral-100);

        &:last-child {
            padding-bottom: 0;
            margin-bottom: 0;
            border-bottom: 0;
        }
    }

    &__chapter-head {
        display: flex;
        align-items: center;
        gap: 16px;
        margin-bottom: 16px;
        letter-spacing: 0.1em;
    }

    &__chapter-num {
        color: var(--at-theme-primary);
    }

    &__chapter-title {
        font-size: 44px;
        letter-spacing: -0.04em;
        line-height: 1.15;
        margin-bottom: 24px;
    }

    &__chapter-body {
        line-height: 1.65;
        letter-spacing: -0.02em;
        margin-bottom: 40px;
    }

    /* Inline image grid (chapter 01) */
    &__inline-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 20px;
    }

    &__inline-fig {
        position: relative;
        margin: 0;
        aspect-ratio: 7 / 5;
        overflow: hidden;
        border-radius: 6px;
        background: var(--at-neutral-100);

        img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.8s ease;
        }

        &:hover img {
            transform: scale(1.04);
        }
    }

    /* Pull-quote (chapter 02) — brand-1 left bar */
    &__pull-quote {
        position: relative;
        margin: 0;
        padding: 10px 0 10px 32px;
        border-left: 4px solid var(--at-theme-primary);

        p {
            letter-spacing: -0.03em;
            line-height: 1.4;
        }
    }

    /* Steps (chapter 03) */
    &__steps {
        margin: 0;
    }

    &__step {
        display: grid;
        grid-template-columns: 80px 1fr 2fr;
        gap: 20px;
        align-items: baseline;
        padding: 22px 0;
        border-top: 1px solid var(--at-neutral-100);

        &:last-child {
            border-bottom: 1px solid var(--at-neutral-100);
        }
    }

    &__step-num {
        color: var(--at-theme-primary);
        letter-spacing: -0.02em;
    }

    &__step-title {
        letter-spacing: -0.03em;
    }

    &__step-desc {
        line-height: 1.55;
        letter-spacing: -0.02em;
    }

    /* Stats (chapter 04) */
    &__stats {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 24px;
    }

    &__stat {
        padding-top: 20px;
        border-top: 1px solid var(--at-neutral-950);
    }

    &__stat-num {
        font-size: 48px;
        letter-spacing: -0.05em;
        margin-bottom: 8px;
    }

    @media #{$lg} {
        &__content-col {
            padding-left: 40px;
        }

        &__chapter-title {
            font-size: 38px;
        }
    }

    @media #{$md} {
        padding-top: 70px;
        padding-bottom: 70px;

        &__sidebar {
            position: static;
            top: auto;
            margin-bottom: 50px;
        }

        &__content-col {
            padding-left: 12px;
        }

        &__chapter-title {
            font-size: 34px;
        }

        &__step {
            grid-template-columns: 60px 1fr;
            row-gap: 8px;
            column-gap: 16px;
        }

        &__step-desc {
            grid-column: 1 / -1;
            padding-left: 76px;
        }

        &__stats {
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
        }

        &__stat-num {
            font-size: 36px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 60px;
        padding-bottom: 60px;

        &__sidebar {
            position: static;
            padding: 24px;
            margin-bottom: 40px;
        }

        &__content-col {
            padding-left: 12px;
        }

        &__chapter {
            padding-bottom: 50px;
            margin-bottom: 50px;
        }

        &__chapter-title {
            font-size: 28px;
        }

        &__chapter-body {
            margin-bottom: 30px;
        }

        &__inline-grid {
            grid-template-columns: 1fr;
            gap: 12px;
        }

        &__inline-fig {
            aspect-ratio: 4 / 3;
        }

        &__pull-quote {
            padding: 8px 0 8px 20px;

            p {
                font-size: 20px !important;
            }
        }

        &__step {
            grid-template-columns: 60px 1fr;
            row-gap: 8px;
        }

        &__step-desc {
            grid-column: 1 / -1;
            padding-left: 76px;
        }

        &__stats {
            grid-template-columns: 1fr;
        }

        &__stat-num {
            font-size: 36px;
        }
    }

    @media #{$xs} {
        &__chapter-head {
            gap: 8px;
        }

        &__chapter-title {
            font-size: 24px;
        }
    }
}

/* =========================================================
   SEC 3 — Pull-quote callout (centered)
   ========================================================= */
.sec-3-portfolio-details-4 {
    background-color: var(--at-neutral-50);

    &__mark {
        display: inline-block;
        font-family: var(--at-ff-heading);
        font-size: 180px;
        line-height: 0.8;
        color: var(--at-theme-primary);
        margin-bottom: -10px;
        letter-spacing: -0.05em;
    }

    &__quote {
        font-size: 34px;
        line-height: 1.4;
        letter-spacing: -0.03em;
        margin-top: 30px;
        padding: 0;
        border: 0;
    }

    &__divider {
        width: 60px;
        height: 1px;
        background: var(--at-neutral-300);
    }

    &__author {
        letter-spacing: -0.02em;
    }

    &__role {
        letter-spacing: 0.1em;
    }

    @media #{$md} {
        padding-top: 70px;
        padding-bottom: 70px;

        &__mark {
            font-size: 140px;
        }

        &__quote {
            font-size: 28px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 60px;
        padding-bottom: 60px;

        &__mark {
            font-size: 120px;
        }

        &__quote {
            font-size: 22px;
        }
    }

    @media #{$xs} {
        &__mark {
            font-size: 100px;
        }

        &__quote {
            font-size: 20px;
        }
    }
}

/* =========================================================
   SEC 4 — Visual showcase 3 rows
   ========================================================= */
.sec-4-portfolio-details-4 {
    background-color: var(--at-neutral-0);

    &__row {
        display: grid;
        gap: 20px;
        margin-bottom: 20px;

        &:last-child {
            margin-bottom: 0;
        }

        &--split {
            grid-template-columns: 6fr 4fr;
        }

        &--full {
            grid-template-columns: 1fr;
        }

        &--triple {
            grid-template-columns: repeat(3, 1fr);
        }
    }

    &__cell {
        position: relative;
        margin: 0;
        aspect-ratio: 16 / 11;
        overflow: hidden;
        border-radius: 6px;
        background: var(--at-neutral-100);

        img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.8s ease;
        }

        &:hover img {
            transform: scale(1.05);
        }

        &--wide {
            aspect-ratio: 13 / 9;
        }

        &--narrow {
            aspect-ratio: 13 / 9;
        }

        &--full {
            aspect-ratio: 22 / 7;
        }
    }

    @media #{$md} {
        padding-top: 50px;
        padding-bottom: 50px;

        &__row {
            gap: 14px;
            margin-bottom: 14px;
        }

        &__cell--full {
            aspect-ratio: 16 / 7;
        }
    }

    @media #{$sm} {
        padding-top: 40px;
        padding-bottom: 40px;

        &__row {
            gap: 12px;
            margin-bottom: 12px;

            &--split,
            &--triple {
                grid-template-columns: 1fr 1fr;
            }
        }

        &__cell--full {
            aspect-ratio: 4 / 3;
        }
    }

    @media #{$xs} {
        padding-top: 40px;
        padding-bottom: 40px;

        &__row {
            gap: 10px;
            margin-bottom: 10px;

            &--split,
            &--triple {
                grid-template-columns: 1fr;
            }
        }

        &__cell--full {
            aspect-ratio: 4 / 3;
        }
    }
}

/* =========================================================
   SEC 5 — Next project banner
   ========================================================= */
.sec-5-portfolio-details-4 {
    position: relative;

    &__link {
        position: relative;
        text-decoration: none;
        color: var(--at-neutral-0);
        display: block;

        &:hover {
            color: var(--at-neutral-0);

            .sec-5-portfolio-details-4__media img {
                transform: scale(1.04);
            }

            .sec-5-portfolio-details-4__disk-inner {
                transform: scale(1.08);
            }
        }
    }

    &__media {
        position: absolute;
        inset: 0;
        overflow: hidden;

        img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.8s ease;
        }
    }

    &__veil {
        position: absolute;
        inset: 0;
        background: rgba(15, 15, 15, 0.68);
    }

    &__content {
        position: relative;
        z-index: 1;
        padding: 140px 0;
    }

    &__eyebrow {
        color: var(--at-theme-primary);
        letter-spacing: 0.15em;
        margin-bottom: 30px;
    }

    &__name {
        font-size: 180px;
        letter-spacing: -0.05em;
        line-height: 0.95;
        color: var(--at-neutral-0);
    }

    &__tagline {
        color: var(--at-neutral-100);
        letter-spacing: -0.03em;
    }

    &__meta {
        color: var(--at-neutral-0);
        letter-spacing: 0.15em;
        opacity: 0.6;
    }

    &__disk {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 220px;
        height: 220px;
        border-radius: 50%;
        border: 1px solid rgba(254, 254, 254, 0.35);
    }

    &__disk-inner {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 140px;
        height: 140px;
        border-radius: 50%;
        background: var(--at-theme-primary);
        color: var(--at-neutral-0);
        transition: transform 0.4s ease;
    }

    @media #{$lg} {
        &__content {
            padding: 110px 0;
        }

        &__name {
            font-size: 140px;
        }

        &__disk {
            width: 180px;
            height: 180px;
        }

        &__disk-inner {
            width: 110px;
            height: 110px;
        }
    }

    @media #{$md} {
        &__content {
            padding: 90px 0;
        }

        &__name {
            font-size: 100px;
        }
    }

    @media #{$sm,$xs} {
        &__content {
            padding: 70px 0;
        }

        &__name {
            font-size: 72px;
        }

        &__tagline {
            font-size: 20px;
        }

        &__eyebrow {
            margin-bottom: 20px;
        }
    }

    @media #{$xs} {
        &__content {
            padding: 60px 0;
        }

        &__name {
            font-size: 56px;
        }

        &__tagline {
            font-size: 18px;
        }
    }
}
