@use '../../utils' as *;

/* Home 12 / Section 2 — Selected Projects */
.sec-2-home-12 {
    background-color: var(--at-neutral-50);
    padding-top: 120px;
}

/* ── Section header ─────────────────────────────── */
.sec-2-home-12__header {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    row-gap: 16px;
    margin-bottom: 64px;
}

.sec-2-home-12__eyebrow {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.24px;
    color: var(--at-theme-primary);
    text-transform: uppercase;
}

.sec-2-home-12__title {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: clamp(48px, 8vw, 124px);
    line-height: 1;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
}

.sec-2-home-12__sub {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
    max-width: 620px;
}

/* ── Cards container ────────────────────────────── */
.sec-2-home-12__cards {
    display: flex;
    flex-direction: column;
    row-gap: 32px;
    margin-inline: auto;
    max-width: 1280px;
}

/* ── Project card ───────────────────────────────── */
.card-home-12-project {
    display: flex;
    align-items: center;
    gap: 48px;
    padding: 32px;
    background-color: var(--at-neutral-0);
    border: 1px solid var(--at-neutral-100);
    border-radius: 24px;
    overflow: hidden;
    text-decoration: none;
    color: inherit;
    box-shadow: 0 18px 40px -28px rgba(0, 0, 0, 0.18);
    transition: border-color 0.3s ease, box-shadow 0.3s ease;

    /* JS-driven stack: ScrollTrigger pins each card; transform-origin keeps the
       scale-down "tucking under" feel anchored at the top of each card. */
    transform-origin: 50% 0%;
    will-change: transform;

    &:hover,
    &:focus-visible {
        border-color: var(--at-neutral-300);
        box-shadow: 0 12px 32px -16px rgba(0, 0, 0, 0.12);
        color: inherit;
    }

    &:hover .card-home-12-project__img,
    &:focus-visible .card-home-12-project__img {
        transform: scale(1.04);
    }

    &:hover .card-home-12-project__title,
    &:focus-visible .card-home-12-project__title {
        color: var(--at-theme-primary);
    }
}

.card-home-12-project__image {
    flex: 0 0 480px;
    width: 480px;
    height: 400px;
    border-radius: 16px;
    overflow: hidden;
    background-color: var(--at-neutral-100);
    position: relative;
}

.card-home-12-project__img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform 0.6s ease;
}

.card-home-12-project__content {
    flex: 1 1 0;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    row-gap: 24px;
}

.card-home-12-project__top {
    display: flex;
    align-items: center;
    column-gap: 12px;
}

.card-home-12-project__num {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.24px;
    color: var(--at-theme-primary);
}

.card-home-12-project__dot {
    display: inline-block;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background-color: var(--at-neutral-300);
}

.card-home-12-project__label {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.24px;
    color: var(--at-neutral-500);
    text-transform: uppercase;
}

.card-home-12-project__title {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 36px;
    line-height: 1;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
    transition: color 0.3s ease;
}

.card-home-12-project__desc {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.5;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
}

.card-home-12-project__tags {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;

    li {
        display: inline-flex;
    }
}

.card-home-12-project__tag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 10.5px 19px;
    border: 1px solid var(--at-neutral-100);
    border-radius: 32px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: -0.24px;
    color: var(--at-neutral-900);
    text-transform: uppercase;
    white-space: nowrap;
    background-color: transparent;
    transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease;

    &.is-filled {
        background-color: var(--at-neutral-900);
        border-color: var(--at-neutral-900);
        color: var(--at-neutral-0);
    }
}

/* ── Responsive ─────────────────────────────────── */
@media #{$xxl} {
    .sec-2-home-12 {
        padding-top: 100px;
        padding-bottom: 100px;
    }

    .card-home-12-project__image {
        flex: 0 0 420px;
        width: 420px;
        height: 360px;
    }

    .card-home-12-project__title {
        font-size: 32px;
    }
}

@media #{$xl} {
    .sec-2-home-12 {
        padding-top: 90px;
        padding-bottom: 90px;
    }

    .card-home-12-project {
        gap: 32px;
        padding: 24px;
    }

    .card-home-12-project__image {
        flex: 0 0 360px;
        width: 360px;
        height: 320px;
    }

    .card-home-12-project__title {
        font-size: 30px;
    }
}

@media #{$lg} {
    .sec-2-home-12 {
        padding-top: 80px;
        padding-bottom: 80px;
    }

    .sec-2-home-12__header {
        margin-bottom: 48px;
    }

    .card-home-12-project {
        gap: 24px;
        padding: 20px;
    }

    .card-home-12-project__image {
        flex: 0 0 320px;
        width: 320px;
        height: 300px;
    }

    .card-home-12-project__content {
        row-gap: 16px;
    }

    .card-home-12-project__title {
        font-size: 28px;
    }
}

@media #{$md} {
    .sec-2-home-12 {
        padding-top: 64px;
        padding-bottom: 64px;
    }

    .sec-2-home-12__header {
        margin-bottom: 40px;
        row-gap: 12px;
    }

    .sec-2-home-12__cards {
        row-gap: 24px;
    }

    .card-home-12-project {
        flex-direction: column;
        align-items: stretch;
        gap: 24px;
        padding: 20px;
    }

    .card-home-12-project__image {
        flex: 0 0 auto;
        width: 100%;
        height: 360px;
    }

    .card-home-12-project__title {
        font-size: 28px;
    }
}

@media #{$sm} {
    .sec-2-home-12 {
        padding-top: 56px;
        padding-bottom: 56px;
    }

    .sec-2-home-12__header {
        margin-bottom: 32px;
        row-gap: 12px;
    }

    .sec-2-home-12__cards {
        row-gap: 20px;
    }

    .card-home-12-project {
        flex-direction: column;
        align-items: stretch;
        gap: 20px;
        padding: 16px;
    }

    .card-home-12-project__image {
        flex: 0 0 auto;
        width: 100%;
        height: 280px;
    }

    .card-home-12-project__content {
        row-gap: 14px;
    }

    .card-home-12-project__title {
        font-size: 24px;
    }

    .card-home-12-project__tag {
        padding: 9px 16px;
        font-size: 11px;
    }
}

@media #{$xs} {
    .sec-2-home-12 {
        padding-top: 48px;
        padding-bottom: 48px;
    }

    .sec-2-home-12__header {
        margin-bottom: 28px;
    }

    .card-home-12-project {
        flex-direction: column;
        align-items: stretch;
        gap: 18px;
        padding: 14px;
        border-radius: 20px;
    }

    .card-home-12-project__image {
        flex: 0 0 auto;
        width: 100%;
        height: 240px;
    }

    .card-home-12-project__content {
        row-gap: 12px;
    }

    .card-home-12-project__title {
        font-size: 22px;
    }

    .card-home-12-project__desc {
        font-size: 15px;
    }

    .card-home-12-project__tag {
        padding: 8px 14px;
        font-size: 10.5px;
    }
}