@use '../../utils' as *;

/* Home 12 / Section 4 — Process Philosophy */
.sec-4-home-12 {
    background-color: var(--at-neutral-50);
    padding-top: 120px;
    padding-bottom: 120px;
}

/* ── Section header ─────────────────────────────── */
.sec-4-home-12__header {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    row-gap: 16px;
    margin-bottom: 64px;
}

.sec-4-home-12__eyebrow {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.96px;
    color: var(--at-neutral-500);
    text-transform: uppercase;
}

.sec-4-home-12__title {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(36px, 5vw, 64px);
    line-height: 1.125;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
    max-width: 980px;
}

/* ── Cards row ──────────────────────────────────── */
.sec-4-home-12__row {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 24px;
    max-width: 1280px;
    margin-inline: auto;
}

/* ── Process card ───────────────────────────────── */
.card-home-12-process {
    display: flex;
    flex-direction: column;
    row-gap: 24px;
    padding: 24px 24px 32px;
    background-color: var(--at-neutral-0);
    border: 1px solid var(--at-neutral-100);
    border-radius: 24px;
    transition: border-color 0.3s ease, box-shadow 0.3s ease;

    &:hover,
    &:focus-within {
        border-color: var(--at-neutral-300);
        box-shadow: 0 12px 32px -16px rgba(0, 0, 0, 0.12);
    }

    &:hover .card-home-12-process__img,
    &:focus-within .card-home-12-process__img {
        transform: scale(1.05);
    }
}

.card-home-12-process__image {
    width: 100%;
    aspect-ratio: 1 / 1;
    background-color: var(--at-neutral-50);
    border-radius: 16px;
    overflow: hidden;
    position: relative;
}

.card-home-12-process__img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform 0.6s ease;
}

.card-home-12-process__text {
    display: flex;
    flex-direction: column;
    row-gap: 8px;
}

.card-home-12-process__title {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 28px;
    line-height: 1;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
}

.card-home-12-process__desc {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.5;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
}

/* ── Responsive ─────────────────────────────────── */
@media #{$xxl} {
    .sec-4-home-12 {
        padding-top: 100px;
        padding-bottom: 100px;
    }
}

@media #{$xl} {
    .sec-4-home-12 {
        padding-top: 90px;
        padding-bottom: 90px;
    }
    .card-home-12-process {
        padding: 20px 20px 28px;
    }
}

@media #{$lg} {
    .sec-4-home-12 {
        padding-top: 80px;
        padding-bottom: 80px;
    }
    .sec-4-home-12__header {
        margin-bottom: 48px;
    }
    .sec-4-home-12__row {
        gap: 20px;
    }
    .card-home-12-process {
        padding: 20px 20px 24px;
        row-gap: 18px;
    }
    .card-home-12-process__title {
        font-size: 24px;
    }
}

@media #{$md} {
    .sec-4-home-12 {
        padding-top: 64px;
        padding-bottom: 64px;
    }
    .sec-4-home-12__header {
        margin-bottom: 40px;
    }
    .sec-4-home-12__row {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 16px;
    }
    .card-home-12-process {
        padding: 18px 18px 24px;
        row-gap: 16px;
    }
    .card-home-12-process__title {
        font-size: 24px;
    }
}

@media #{$sm} {
    .sec-4-home-12 {
        padding-top: 56px;
        padding-bottom: 56px;
    }
    .sec-4-home-12__header {
        margin-bottom: 32px;
        row-gap: 12px;
    }
    .sec-4-home-12__row {
        grid-template-columns: 1fr;
        gap: 16px;
        max-width: 480px;
    }
    .card-home-12-process {
        padding: 18px 18px 24px;
        row-gap: 16px;
        border-radius: 20px;
    }
    .card-home-12-process__title {
        font-size: 24px;
    }
}

@media #{$xs} {
    .sec-4-home-12 {
        padding-top: 48px;
        padding-bottom: 48px;
    }
    .sec-4-home-12__header {
        margin-bottom: 28px;
        row-gap: 12px;
    }
    .sec-4-home-12__row {
        grid-template-columns: 1fr;
        gap: 14px;
    }
    .card-home-12-process {
        padding: 16px 16px 20px;
        row-gap: 14px;
        border-radius: 18px;
    }
    .card-home-12-process__title {
        font-size: 22px;
    }
    .card-home-12-process__desc {
        font-size: 15px;
    }
}
