@use '../../utils' as *;

/* ===========================================================
   Section 2 — Home 15 (About Us)
   =========================================================== */

.sec-2-home-15 {
    background-color: var(--at-neutral-0);
    border-top: 1px solid var(--at-neutral-200);

    /* ---- Top heading ---- */
    &__heading {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 48px;
        line-height: 1.08;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950);

        @media #{$xl} {
            font-size: 42px;
        }

        @media #{$lg} {
            font-size: 38px;
        }

        @media #{$md} {
            font-size: 34px;
        }

        @media #{$sm} {
            font-size: 30px;
        }

        @media #{$xs} {
            font-size: 26px;
        }
    }

    /* ---- Media (big image) ---- */
    &__media-1 {
        position: relative;
        width: 100%;
        aspect-ratio: 553 / 533;
        overflow: hidden;
        border-radius: 16px;
        background-color: var(--at-neutral-200);
    }

    &__media-1-img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    /* ---- Floating glass badge on media-1 ---- */
    &__media-1-badge {
        position: absolute;
        right: 20px;
        bottom: 20px;
        z-index: 2;
        display: inline-flex;
        align-items: center;
        gap: 14px;
        padding: 12px 18px;
        border-radius: 14px;
        background-color: rgba(37, 99, 235, 0.32);
        border: 1px solid rgba(255, 255, 255, 0.28);
        backdrop-filter: blur(16px) saturate(1.2);
        -webkit-backdrop-filter: blur(16px) saturate(1.2);
        box-shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
        color: #fff;
        max-width: calc(100% - 32px);

        @media #{$md} {
            right: 16px;
            bottom: 16px;
            padding: 10px 14px;
            gap: 12px;
        }

        @media #{$sm}, #{$xs} {
            right: 12px;
            bottom: 12px;
            padding: 10px 12px;
            gap: 10px;
            border-radius: 12px;
        }
    }

    &__media-1-badge-dot {
        position: relative;
        flex-shrink: 0;
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background-color: #4ade80;
        box-shadow: 0 0 0 0 rgba(74, 222, 128, 0.7);
        animation: sec-2-home-15-pulse 1.8s ease-out infinite;

        @media (prefers-reduced-motion: reduce) {
            animation: none;
        }
    }

    &__media-1-badge-text {
        display: inline-flex;
        flex-direction: column;
        line-height: 1.2;
        min-width: 0;
    }

    &__media-1-badge-title {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 14px;
        letter-spacing: -0.01em;
        color: #fff;

        @media #{$sm}, #{$xs} {
            font-size: 13px;
        }
    }

    &__media-1-badge-meta {
        font-family: var(--at-ff-body);
        font-weight: 400;
        font-size: 12px;
        letter-spacing: 0;
        color: rgba(255, 255, 255, 0.82);

        @media #{$xs} {
            font-size: 11px;
        }
    }

    /* ---- Right column content ---- */
    &__content {
        display: flex;
        flex-direction: column;
        gap: 40px;

        @media #{$xl} {
            gap: 32px;
        }

        @media #{$md}, #{$sm}, #{$xs} {
            gap: 24px;
        }
    }

    &__body {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 24px;
        line-height: 1.3;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950);
        max-width: 620px;

        @media #{$xl} {
            font-size: 22px;
        }

        @media #{$lg}, #{$md} {
            font-size: 20px;
        }

        @media #{$sm}, #{$xs} {
            font-size: 18px;
        }
    }

    /* ---- Features 2x2 ---- */
    &__features {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 20px 39px;
        max-width: 620px;

        @media #{$sm}, #{$xs} {
            grid-template-columns: 1fr;
            gap: 14px;
        }
    }

    &__feature {
        display: flex;
        align-items: center;
        gap: 12px;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.4;
        letter-spacing: -0.02em;
        color: var(--at-neutral-700);

        @media #{$xs} {
            font-size: 15px;
        }
    }

    &__feature-icon {
        flex-shrink: 0;
        color: var(--at-neutral-900);
    }

    /* ---- Compact contact form ---- */
    &__form {
        display: flex;
        flex-direction: column;
        gap: 20px;
        max-width: 620px;

        @media #{$md}, #{$sm}, #{$xs} {
            gap: 16px;
        }
    }

    &__form-label {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 18px;
        line-height: 1.4;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900);

        @media #{$sm}, #{$xs} {
            font-size: 16px;
        }
    }

    &__form-row {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0 32px;

        @media #{$sm}, #{$xs} {
            grid-template-columns: 1fr;
            gap: 0;
        }
    }

    &__form-textarea {
        min-height: 96px;
    }

    &__form-actions {
        margin-top: 12px;
        margin-bottom: 0;
    }

    /* ---- Floating 3D cube object ---- */
    &__object {
        position: absolute;
        right: 24px;
        bottom: -40px;
        z-index: 1;
        pointer-events: none;

        @media #{$xl} {
            right: 16px;
            transform: scale(0.85);
            transform-origin: right bottom;
        }

        @media #{$lg}, #{$md}, #{$sm}, #{$xs} {
            display: none;
        }
    }

    /* ---- Stats with odometer ---- */
    &__stats {
        margin-left: 0;
        margin-right: 0;
    }

    &__stat {
        display: flex;
        flex-direction: column;
    }

    &__stat-num {
        display: inline-flex;
        align-items: baseline;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 84px;
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);

        @media #{$xl} {
            font-size: 72px;
        }

        @media #{$lg} {
            font-size: 64px;
        }

        @media #{$md} {
            font-size: 56px;
        }

        @media #{$sm} {
            font-size: 56px;
        }

        @media #{$xs} {
            font-size: 48px;
        }

        .odometer {
            font: inherit;
            color: inherit;
        }

        .odometer-inside,
        .odometer-digit,
        .odometer-formatting-mark {
            font: inherit !important;
            color: inherit !important;
        }
    }

    &__stat-suffix {
        display: inline-block;
        font: inherit;
        color: inherit;
    }

    &__stat-label {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.4;
        letter-spacing: -0.02em;
        color: var(--at-neutral-500);
        max-width: 200px;

        @media #{$xs} {
            font-size: 14px;
        }
    }

    /* ---- Secondary image ---- */
    &__media-2 {
        position: relative;
        width: 100%;
        aspect-ratio: 322 / 401;
        overflow: hidden;
        border-radius: 16px;
        background-color: var(--at-neutral-200);
    }

    &__media-2-img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    /* ---- Floating glass badge on media-2 (compact) ---- */
    &__media-2-badge {
        position: absolute;
        right: 14px;
        bottom: 14px;
        z-index: 2;
        display: inline-flex;
        align-items: center;
        gap: 10px;
        padding: 10px 14px;
        border-radius: 12px;
        background-color: rgba(37, 99, 235, 0.32);
        border: 1px solid rgba(255, 255, 255, 0.28);
        backdrop-filter: blur(16px) saturate(1.2);
        -webkit-backdrop-filter: blur(16px) saturate(1.2);
        box-shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
        color: #fff;
        max-width: calc(100% - 28px);

        @media #{$xs} {
            right: 10px;
            bottom: 10px;
            padding: 8px 11px;
            gap: 8px;
            border-radius: 10px;
        }
    }

    &__media-2-badge-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
        width: 28px;
        height: 28px;
        border-radius: 50%;
        background-color: rgba(255, 255, 255, 0.18);
        color: #ffd166;

        @media #{$xs} {
            width: 24px;
            height: 24px;

            svg {
                width: 14px;
                height: 14px;
            }
        }
    }

    &__media-2-badge-text {
        display: inline-flex;
        flex-direction: column;
        line-height: 1.2;
        min-width: 0;
    }

    &__media-2-badge-title {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 13px;
        letter-spacing: -0.01em;
        color: #fff;

        @media #{$xs} {
            font-size: 12px;
        }
    }

    &__media-2-badge-meta {
        font-family: var(--at-ff-body);
        font-weight: 400;
        font-size: 11px;
        color: rgba(255, 255, 255, 0.82);
    }

    /* ---- Statement (shape icon + text) ---- */
    &__statement {
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        gap: 32px;
        max-width: 323px;

        @media #{$md}, #{$sm}, #{$xs} {
            gap: 20px;
        }
    }

    &__statement-icon {
        width: 40px;
        height: 40px;
        object-fit: contain;
        flex-shrink: 0;
    }

    &__statement-text {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 20px;
        line-height: 1.3;
        letter-spacing: -0.02em;
        color: var(--at-neutral-500);

        @media #{$xl} {
            font-size: 18px;
        }

        @media #{$xs} {
            font-size: 16px;
        }
    }
}

@keyframes sec-2-home-15-pulse {
    0% {
        box-shadow: 0 0 0 0 rgba(74, 222, 128, 0.7);
    }

    70% {
        box-shadow: 0 0 0 12px rgba(74, 222, 128, 0);
    }

    100% {
        box-shadow: 0 0 0 0 rgba(74, 222, 128, 0);
    }
}
