@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-9-home-7 (Marquee — carouselTicker + GSAP scroll-move)
/*  Structure mirrors Home 3 sec-2: .carouselTicker > ul.carouselTicker__list
/*----------------------------------------*/

.sec-9-home-7 {
    background: #0f0f0f;
    padding: 40px 0;
    overflow: hidden;

    @media #{$md,$sm,$xs} {
        padding: 28px 0;
    }

    // Inner wrapper (matches Home 3: bg + carouselTicker on same node)
    &__ticker {
        background: #0f0f0f;
    }

    &__row {
        position: relative;
        width: 100%;
        overflow: hidden;
    }

    &__list {
        gap: 31px !important;
        white-space: nowrap;

        @media #{$md,$sm,$xs} {
            gap: 18px !important;
        }
    }

    &__item {
        font-family: var(--at-heading-font);
        font-size: 48px;
        font-weight: 600;
        line-height: 1;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-0, #fefefe);
        flex-shrink: 0;

        @media #{$xl,$lg} {
            font-size: 42px;
        }

        @media #{$md} {
            font-size: 32px;
            line-height: 1;
        }

        @media #{$sm,$xs} {
            font-size: 24px;
            line-height: 40px;
        }

        &--sm {
            font-size: 36px;
            letter-spacing: -0.05em;
            text-transform: none;

            @media #{$xl,$lg} {
                font-size: 32px;
            }

            @media #{$md} {
                font-size: 26px;
            }

            @media #{$sm,$xs} {
                font-size: 20px;
            }
        }
    }

    &__sep {
        flex-shrink: 0;
        width: 40px;
        height: 40px;
        flex: 0 0 40px;
        display: inline-flex;
        align-items: center;
        justify-content: center;

        img {
            width: 100%;
            height: 100%;
            display: block;
        }

        @media #{$sm,$xs} {
            width: 28px;
            height: 28px;
            flex-basis: 28px;
        }
    }
}