@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-4-home-10 (Home 10 — Our services)
/*----------------------------------------*/

.sec-4-home-10 {
    position: relative;
    padding-top: clamp(56px, 7vw, 120px);
    padding-bottom: clamp(64px, 9vw, 140px);
    background: var(--at-neutral-900, #1d1d1d);
    color: var(--at-neutral-0, #fefefe);

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__stage {
        display: flex;
        flex-direction: column;
        gap: clamp(32px, 4vw, 48px);

        @media (min-width: 992px) {
            display: grid;
            grid-template-columns: minmax(0, 1fr) minmax(240px, 0.82fr) minmax(0, 1fr);
            grid-template-rows: auto auto;
            gap: clamp(20px, 2vw, 32px);
            align-items: start;
        }
    }

    &__title-block {
        text-align: center;

        @media (min-width: 992px) {
            grid-column: 2;
            grid-row: 1 / span 2;
            align-self: center;
            justify-self: center;
            z-index: 1;
            max-width: min(520px, 100%);
            padding: clamp(12px, 2vw, 28px) 0;
            pointer-events: none;

            .sec-4-home-10__eyebrow,
            .sec-4-home-10__title {
                pointer-events: auto;
            }
        }
    }

    &__eyebrow-text {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0, #fefefe);
    }

    &__eyebrow-arrow {
        flex-shrink: 0;
        color: var(--at-neutral-0, #fefefe);
    }

    &__title {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(28px, 3.6vw, 56px);
        line-height: 1.08;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-0, #fefefe);
        text-wrap: balance;
    }

    &__card {
        position: relative;
        z-index: 2;
        min-width: 0;
        width: 100%;

        @media (min-width: 992px) {
            &--pos1 {
                grid-column: 1;
                grid-row: 1;
                justify-self: start;
                max-width: 550px;
            }

            &--pos2 {
                grid-column: 3;
                grid-row: 1;
                justify-self: end;
                max-width: 410px;
            }

            &--pos3 {
                grid-column: 1;
                grid-row: 2;
                justify-self: start;
                max-width: 410px;
            }

            &--pos4 {
                grid-column: 3;
                grid-row: 2;
                justify-self: end;
                max-width: 560px;
            }
        }
    }

    &__card-inner {
        display: flex;
        flex-direction: column;
        gap: 8px;
        height: 100%;
    }

    &__visual {
        position: relative;
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-800, #2a2a2a);

        @media (max-width: 991.98px) {
            aspect-ratio: 16 / 10;
        }
    }

    &__visual-link {
        display: block;
        width: 100%;
        height: 100%;
        color: inherit;
        text-decoration: none;
        transition: opacity 0.3s ease;

        &:hover {
            opacity: 0.94;
        }

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    &__overlay {
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        min-height: 46%;
        padding: clamp(22px, 2.4vw, 40px) clamp(20px, 2.4vw, 44px);
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
        background: linear-gradient(180deg, rgba(26, 26, 26, 0) 8%, rgba(26, 26, 26, 0.78) 100%);
        pointer-events: none;
    }

    &__excerpt {
        max-width: min(420px, 100%);
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(15px, 1.05vw, 18px);
        line-height: 1.4;
        letter-spacing: -0.02em;
        color: var(--at-neutral-0, #fefefe);
    }

    &__bar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        min-height: 88px;
        padding: 16px clamp(20px, 2.2vw, 40px);
        border-radius: 16px;
        background: var(--at-neutral-0, #fefefe);
    }

    &__service-name {
        flex: 1;
        min-width: 0;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(20px, 1.75vw, 32px);
        line-height: 1.1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__expand {
        flex-shrink: 0;
        width: 44px;
        height: 44px;
        padding: 0;
        border: 1px solid var(--at-neutral-200, #e0e0e0);
        border-radius: 50%;
        background: transparent;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        transition: border-color 0.25s ease, background 0.25s ease;

        &:hover {
            border-color: var(--at-neutral-900, #1d1d1d);
            background: var(--at-neutral-50, #f7f7f7);
        }
    }

    &__expand-icon {
        position: relative;
        width: 14px;
        height: 14px;
        display: block;

        &::before,
        &::after {
            content: '';
            position: absolute;
            background: var(--at-neutral-900, #1d1d1d);
            border-radius: 1px;
        }

        &::before {
            left: 0;
            right: 0;
            top: 50%;
            height: 2px;
            transform: translateY(-50%);
        }

        &::after {
            top: 0;
            bottom: 0;
            left: 50%;
            width: 2px;
            transform: translateX(-50%);
        }
    }
}