@use '../../utils' as *;

/*------------------------------------------------------------------
  Home 8 — Section 6 (Selected works)
------------------------------------------------------------------*/

.sec-6-home-8 {
    background-color: var(--at-neutral-50);
    padding-top: clamp(70px, 6vw, 110px);
    padding-bottom: clamp(70px, 6vw, 110px);

    &__container {
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__top {
        margin-bottom: clamp(28px, 3.2vw, 60px);
    }

    &__kicker {
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-900);
    }

    &__kicker-icon {
        display: inline-flex;
        color: var(--at-neutral-900);
        line-height: 0;
    }

    &__view-all {
        font-size: 16px;
        font-weight: 500;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900);
        text-decoration: underline;
        text-underline-offset: 3px;
    }

    &__grid {
        display: grid;
        gap: 30px;
        grid-template-columns: 408px 1fr 408px;
        grid-auto-rows: min-content;
        align-items: start;

        @media (max-width: 1399px) {
            grid-template-columns: 1fr;
        }
    }

    &__card {
        display: flex;
        flex-direction: column;
        gap: 8px;
        text-decoration: none;
        color: inherit;
        will-change: transform;

        &:hover .sec-6-home-8__img img {
            transform: scale(1.06);
            filter: brightness(1.05);
        }
    }

    &__img {
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-200);

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
            transition: transform 0.35s ease, filter 0.35s ease;
        }
    }

    &__meta {
        height: 88px;
        border-radius: 16px;
        background: var(--at-neutral-0);
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 0 45px;
        overflow: hidden;
    }

    &__title {
        font-size: 36px;
        font-weight: 600;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
    }

    &__plus {
        display: inline-flex;
        color: var(--at-neutral-900);
        line-height: 0;
    }

    // Sizes
    &__card--sm .sec-6-home-8__img {
        height: 320px;
    }

    &__card--md .sec-6-home-8__img {
        height: 350px;
    }

    &__card--lg .sec-6-home-8__img {
        height: 450px;
    }

    @media (min-width: 1441px) {

        // Sizes
        &__card--sm .sec-6-home-8__img {
            height: 358px;
        }

        &__card--md .sec-6-home-8__img {
            height: 632px;
        }

        &__card--lg .sec-6-home-8__img {
            height: 751px;
        }
    }

 // Desktop positioning to match the mosaic
    @media (min-width: 1400px) {
        &__card--lt {
            grid-column: 1;
            grid-row: 1;
            margin-top: 67px;
        }

        &__card--lb {
            grid-column: 1;
            grid-row: 3;
            margin-top: 0;
        }

        &__card--ct {
            grid-column: 2;
            grid-row: 1;
        }

        &__card--cm {
            grid-column: 2;
            grid-row: 2;
            margin-top: 52px;
        }

        &__card--cb {
            grid-column: 2;
            grid-row: 3;
        }

        &__card--rt {
            grid-column: 3;
            grid-row: 1;
            margin-top: 260px;
        }

        &__card--rb {
            grid-column: 3;
            grid-row: 3;
            margin-top: 0;
        }


    }



    @media (max-width: 767px) {
        &__grid {
            gap: 18px;
        }

        &__meta {
            padding: 0 18px;
            height: 70px;
        }

        &__title {
            font-size: 24px;
        }
    }
}