@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-2-home-9 (Home 9 — stats / odometer row)
/*----------------------------------------*/

.sec-2-home-9 {
    position: relative;
    overflow: hidden;

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__stats {
        display: grid;
        grid-template-columns: repeat(5, minmax(0, 1fr));
        column-gap: clamp(16px, 2vw, 32px);
        row-gap: clamp(28px, 2.2vw, 32px);
        align-items: start;
        justify-items: start;
        padding-top: clamp(48px, 5.1vw, 98px);
        padding-bottom: clamp(28px, 3.2vw, 62px);

        @media #{$lg} {
            column-gap: 20px;
        }

        @media #{$md,$sm} {
            grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        @media #{$xs} {
            grid-template-columns: 1fr;
        }
    }

    &__stat {
        max-width: 232px;
        width: 100%;

        @media #{$xs} {
            max-width: 100%;
        }
    }

    &__value {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(40px, 4.4vw, 84px);
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
        margin-bottom: clamp(20px, 1.9vw, 29px);

        .odometer {
            letter-spacing: -0.05em;
        }
    }

    &__label {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.35;
        letter-spacing: -0.02em;
        color: var(--at-neutral-950);
    }

    &__lines {
        width: 100%;
        line-height: 0;

        img {
            display: block;
            width: 100%;
            height: auto;
            max-width: 1720px;
        }
    }
}
