@use '../../utils' as *;

/* ===========================================================
   Footer 15 — Fashion Agency

   Layout: 2x2 panel grid of dark rounded cards.
   Row 1: nav+social (64.5%)  |  newsletter (35.5%)
   Row 2: brand+services (35.5%) | contact+legal (64.5%)

   Always-dark surface (does not swap in dark mode) — uses
   literal hex tokens to match Figma frame intent.
   =========================================================== */

.footer-15 {
    --footer15-panel-bg: #0f0f0f;
    --footer15-panel-radius: 32px;
    --footer15-panel-pad: 64px;
    --footer15-panel-min-h: 369px;
    --footer15-gap: 8px;
    --footer15-text: #fefefe;
    --footer15-muted: #b7b7b7;
    --footer15-faint: #585959;
    --footer15-input-bg: #1d1d1d;
    --footer15-stroke: rgba(255, 255, 255, 0.3);

    padding: 80px 8px 80px 5px;
    background-color: var(--at-neutral-0);
    color: var(--footer15-text);
}

/* ── Grid ────────────────────────────────────────────────── */
/* 3-col grid with staggered spans: row 1 = 2/3 + 1/3,
   row 2 = 1/3 + 2/3 (zigzag panel layout). */
.footer-15__grid {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: var(--footer15-gap);
}

.footer-15__panel {
    position: relative;
    overflow: hidden;
    min-height: var(--footer15-panel-min-h);
    padding: var(--footer15-panel-pad);
    background-color: var(--footer15-panel-bg);
    border-radius: var(--footer15-panel-radius);
    display: flex;
    flex-direction: column;
}

.footer-15__panel--nav {
    grid-column: span 2;
}

.footer-15__panel--news {
    grid-column: span 1;
    justify-content: center;
}

.footer-15__panel--brand {
    grid-column: span 1;
    justify-content: space-between;
    gap: 48px;
}

.footer-15__panel--contact {
    grid-column: span 2;
    justify-content: space-between;
    gap: 32px;
}

/* ── Panel 1 — Nav + social ─────────────────────────────── */
.footer-15__panel--nav {
    flex-direction: row;
    align-items: flex-end;
    justify-content: space-between;
    gap: 48px;
}

.footer-15__nav-wrap {
    display: flex;
    align-items: flex-start;
    gap: 56px;
    flex: 0 0 auto;
}

.footer-15__nav {
    display: flex;
    flex-direction: column;
    gap: 14px;

    li {
        position: relative;
    }

    a {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        font-family: var(--at-ff-heading);
        font-weight: 400;
        font-size: 22px;
        line-height: 1.1;
        letter-spacing: -0.05em;
        color: var(--footer15-muted);
        text-decoration: none;
        transition: color 0.3s ease;

        &:hover,
        &:focus-visible,
        &.is-current {
            color: var(--footer15-text);
        }
    }
}

.footer-15__nav-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: currentColor;
    transition: transform 0.3s ease;

    a:hover &,
    a:focus-visible & {
        transform: translate(2px, -2px);
    }
}

.footer-15__social {
    flex: 1 1 auto;
    max-width: 360px;
    display: flex;
    flex-direction: column;
    gap: 26px;
    align-items: flex-start;
}

.footer-15__eyebrow {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.16em;
    color: var(--footer15-text);
    text-transform: uppercase;
    opacity: 0.5;
}

.footer-15__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;

    a {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        padding: 10px 19px;
        border: 1px solid var(--footer15-stroke);
        border-radius: 32px;
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 14px;
        line-height: 1.15;
        letter-spacing: -0.02em;
        color: var(--footer15-text);
        text-decoration: none;
        transition: background-color 0.3s ease, border-color 0.3s ease, color 0.3s ease;

        svg {
            transition: transform 0.3s ease;
        }

        &:hover,
        &:focus-visible {
            background-color: var(--at-theme-primary);
            border-color: var(--at-theme-primary);
            color: var(--footer15-text);

            svg {
                transform: translate(2px, -2px);
            }
        }
    }
}

/* ── Panel 2 — Newsletter ───────────────────────────────── */
.footer-15__news-bg {
    position: absolute;
    inset: 0;
    background-position: center center;
    background-repeat: no-repeat;
    background-size: cover;
    opacity: 0.42;
    pointer-events: none;
    z-index: 0;
}

.footer-15__news-inner {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    gap: 20px;
    width: 100%;
    max-width: 410px;
    margin-top: auto;
    margin-bottom: auto;
}

.footer-15__news-label {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 14px;
    line-height: 1.25;
    letter-spacing: -0.05em;
    color: var(--footer15-text);
    text-transform: uppercase;
}

.footer-15__form {
    display: flex;
    flex-direction: column;
    gap: 8px;
    width: 100%;
}

input.footer-15__form-input {
    width: 100%;
    height: 50px;
    padding: 0 24px;
    background-color: var(--footer15-input-bg);
    border: 1px solid transparent;
    border-radius: 16px;
    font-family: var(--at-ff-heading);
    font-weight: 400;
    font-size: 16px;
    line-height: 1.5;
    letter-spacing: -0.05em;
    color: var(--footer15-text);
    outline: none;
    transition: border-color 0.3s ease;

    &::placeholder {
        color: rgba(254, 254, 254, 0.5);
    }

    &:focus {
        border-color: rgba(255, 255, 255, 0.25);
    }
}

.footer-15__form-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    width: 100%;
    height: 50px;
    padding: 0 24px;
    background-color: var(--footer15-input-bg);
    border: 0;
    border-radius: 16px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    line-height: 1;
    letter-spacing: 0.04em;
    color: var(--footer15-text);
    text-transform: uppercase;
    cursor: pointer;
    transition: background-color 0.3s ease, color 0.3s ease;

    svg {
        transition: transform 0.3s ease;
    }

    &:hover,
    &:focus-visible {
        background-color: var(--at-theme-primary);

        svg {
            transform: translate(2px, -2px);
        }
    }
}

/* ── Panel 3 — Brand + services ─────────────────────────── */
.footer-15__brand-head {
    display: flex;
    align-items: flex-start;
    gap: 22px;
}

.footer-15__brand-mark {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: auto;
    text-decoration: none;
}

.footer-15__brand-icon {
    display: block;
    max-width: 100%;
    height: auto;
}

.footer-15__brand-title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(36px, 3.4vw, 48px);
    line-height: 1.08;
    letter-spacing: -0.05em;
    margin: 0;
}

.footer-15__brand-title-strong {
    color: var(--footer15-text);
}

.footer-15__brand-title-muted {
    color: var(--footer15-faint);
}

.footer-15__services {
    display: grid;
    grid-template-columns: 1fr 1fr;
    column-gap: 32px;
    row-gap: 14px;

    a {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--footer15-muted);
        text-decoration: none;
        transition: color 0.3s ease;

        &:hover,
        &:focus-visible {
            color: var(--footer15-text);

            .footer-15__service-icon {
                transform: translate(2px, -2px);
            }
        }
    }

    .is-current a {
        color: var(--footer15-text);
    }
}

.footer-15__service-dot {
    flex-shrink: 0;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: var(--at-theme-primary);
}

.footer-15__service-icon {
    display: inline-flex;
    align-items: center;
    color: currentColor;
    transition: transform 0.3s ease;
}

/* ── Panel 4 — Contact + legal ──────────────────────────── */
.footer-15__contact-row {
    display: grid;
    grid-template-columns: 1.45fr 1fr;
    gap: 48px;
    align-items: start;
}

.footer-15__intro {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 20px;
    line-height: 1.4;
    letter-spacing: -0.02em;
    color: var(--footer15-text);
    max-width: 460px;
}

.footer-15__contact {
    display: flex;
    flex-direction: column;
    gap: 24px;
    font-style: normal;
}

.footer-15__contact-line {
    display: inline-block;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 24px;
    line-height: 1.2;
    letter-spacing: -0.05em;
    color: var(--footer15-text);
    text-decoration: none;
    transition: color 0.3s ease;

    &[href]:hover,
    &[href]:focus-visible {
        color: var(--at-theme-primary);
    }
}

.footer-15__legal {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 24px;
    flex-wrap: wrap;
}

.footer-15__copy {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.25;
    letter-spacing: -0.02em;
    color: rgba(254, 254, 254, 0.5);
}

.footer-15__legal-links {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;

    a {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 14px;
        line-height: 1.25;
        letter-spacing: -0.02em;
        color: rgba(254, 254, 254, 0.5);
        text-decoration: none;
        transition: color 0.3s ease;

        &:hover,
        &:focus-visible {
            color: var(--footer15-text);
        }
    }
}

/* ── Responsive ─────────────────────────────────────────── */
@media #{$xxl} {
    .footer-15 {
        --footer15-panel-pad: 52px;
        --footer15-panel-min-h: 340px;
    }

    .footer-15__nav-wrap {
        gap: 44px;
    }

    .footer-15__nav a {
        font-size: 20px;
    }

    .footer-15__intro {
        font-size: 18px;
    }

    .footer-15__contact-line {
        font-size: 22px;
    }
}

@media #{$xl} {
    .footer-15 {
        --footer15-panel-pad: 44px;
        --footer15-panel-min-h: 320px;
    }

    .footer-15__nav-wrap {
        gap: 36px;
    }

    .footer-15__nav a {
        font-size: 18px;
    }

    .footer-15__brand-title {
        font-size: 38px;
    }

    .footer-15__intro {
        font-size: 17px;
    }

    .footer-15__contact-line {
        font-size: 20px;
    }

    .footer-15__contact-row {
        gap: 32px;
    }
}

/* Tablet landscape — stack panel 1 (nav + social) vertically */
@media #{$lg} {
    .footer-15 {
        padding: 56px 8px 56px 5px;
        --footer15-panel-pad: 40px;
        --footer15-panel-min-h: 0;
    }

    .footer-15__panel--nav {
        flex-direction: column;
        align-items: flex-start;
        gap: 36px;
    }

    .footer-15__nav-wrap {
        gap: 56px;
    }

    .footer-15__nav a {
        font-size: 18px;
    }

    .footer-15__brand-title {
        font-size: 36px;
    }

    .footer-15__intro {
        font-size: 16px;
    }

    .footer-15__contact-line {
        font-size: 20px;
    }

    .footer-15__contact-row {
        gap: 24px;
    }
}

/* Tablet portrait — single column stack */
@media #{$md} {
    .footer-15 {
        padding: 48px 8px 48px 5px;
        --footer15-panel-pad: 32px;
        --footer15-panel-min-h: 0;
    }

    .footer-15__grid {
        grid-template-columns: 1fr;
        gap: 8px;
    }

    .footer-15__panel--nav,
    .footer-15__panel--news,
    .footer-15__panel--brand,
    .footer-15__panel--contact {
        grid-column: 1 / -1;
    }

    .footer-15__panel--nav {
        flex-direction: column;
        align-items: flex-start;
        gap: 32px;
    }

    .footer-15__nav-wrap {
        gap: 56px;
    }

    .footer-15__nav a {
        font-size: 18px;
    }

    .footer-15__panel--news {
        min-height: 280px;
    }

    .footer-15__news-inner {
        max-width: 100%;
    }

    .footer-15__brand-title {
        font-size: 36px;
    }

    .footer-15__contact-row {
        grid-template-columns: 1fr;
        gap: 28px;
    }

    .footer-15__intro {
        font-size: 18px;
        max-width: 100%;
    }

    .footer-15__contact-line {
        font-size: 22px;
    }
}

/* Phone */
@media #{$sm} {
    .footer-15 {
        padding: 40px 8px 40px 5px;
        --footer15-panel-pad: 24px;
        --footer15-gap: 6px;
    }

    .footer-15__grid {
        grid-template-columns: 1fr;
        gap: 6px;
    }

    .footer-15__panel--nav,
    .footer-15__panel--news,
    .footer-15__panel--brand,
    .footer-15__panel--contact {
        grid-column: 1 / -1;
    }

    .footer-15__panel--nav {
        flex-direction: column;
        align-items: flex-start;
        gap: 28px;
    }

    .footer-15__nav-wrap {
        gap: 40px;
    }

    .footer-15__nav a {
        font-size: 17px;
    }

    .footer-15__panel--news {
        min-height: 260px;
    }

    .footer-15__news-inner {
        max-width: 100%;
        gap: 16px;
    }

    .footer-15__brand-head {
        gap: 16px;
    }

    .footer-15__brand-title {
        font-size: 32px;
    }

    .footer-15__contact-row {
        grid-template-columns: 1fr;
        gap: 24px;
    }

    .footer-15__intro {
        font-size: 16px;
        max-width: 100%;
    }

    .footer-15__contact-line {
        font-size: 20px;
    }

    .footer-15__legal {
        gap: 16px;
    }
}

/* Small phone (≤574.98px) — explicit rules; ranges do NOT cascade */
@media #{$xs} {
    .footer-15 {
        padding: 32px 8px 32px 5px;
        --footer15-panel-pad: 20px;
        --footer15-panel-radius: 24px;
        --footer15-gap: 5px;
    }

    .footer-15__grid {
        grid-template-columns: 1fr;
        gap: 5px;
    }

    .footer-15__panel--nav,
    .footer-15__panel--news,
    .footer-15__panel--brand,
    .footer-15__panel--contact {
        grid-column: 1 / -1;
    }

    .footer-15__panel--nav {
        flex-direction: column;
        align-items: flex-start;
        gap: 24px;
    }

    .footer-15__nav-wrap {
        flex-direction: column;
        gap: 18px;
    }

    .footer-15__nav {
        gap: 10px;
    }

    .footer-15__nav a {
        font-size: 18px;
    }

    .footer-15__tags {
        gap: 6px;

        a {
            padding: 8px 14px;
            font-size: 13px;
        }
    }

    .footer-15__panel--news {
        min-height: 240px;
    }

    .footer-15__news-inner {
        max-width: 100%;
        gap: 14px;
    }

    input.footer-15__form-input,
    .footer-15__form-btn {
        height: 46px;
        font-size: 14px;
        padding: 0 18px;
    }

    .footer-15__brand-head {
        flex-direction: column;
        align-items: flex-start;
        gap: 14px;
    }

    .footer-15__brand-mark {
        width: 40px;
    }

    .footer-15__brand-title {
        font-size: 28px;
    }

    .footer-15__services {
        grid-template-columns: 1fr;
        row-gap: 10px;
    }

    .footer-15__services a {
        font-size: 15px;
    }

    .footer-15__contact-row {
        grid-template-columns: 1fr;
        gap: 20px;
    }

    .footer-15__intro {
        font-size: 15px;
    }

    .footer-15__contact {
        gap: 16px;
    }

    .footer-15__contact-line {
        font-size: 18px;
    }

    .footer-15__legal {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }

    .footer-15__copy {
        font-size: 14px;
    }

    .footer-15__legal-links {
        gap: 12px;

        a {
            font-size: 13px;
        }
    }
}
