@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-5-home-10 (Home 10 — About + metrics)
/*----------------------------------------*/

.sec-5-home-10 {
    position: relative;
    padding-top: clamp(48px, 6vw, 100px);
    padding-bottom: clamp(56px, 8vw, 140px);
    background: var(--at-neutral-50, #f2f2f2);

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__intro-row {
        margin-bottom: clamp(40px, 6vw, 88px);
        position: relative;
        z-index: 3;
    }

    &__eyebrow-text {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__eyebrow {
        transition: opacity 0.25s ease;

        &:hover {
            opacity: 0.75;
        }
    }

    &__title {
        max-width: 1250px;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(28px, 3.4vw, 48px);
        line-height: 1.15;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-950, #0f0f0f);
        text-wrap: balance;
    }

    &__cta {
        height: 50px;
        padding: 14px 27px;
        border-radius: 50px;
        background: var(--at-neutral-900, #1d1d1d);
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0, #fefefe) !important;
        text-decoration: none !important;
        white-space: nowrap;
        transition: background 0.25s ease, color 0.25s ease;

        &:hover {
            background: var(--at-theme-primary);
            color: var(--at-neutral-0) !important;
        }
    }

    &__cta-arrow {
        flex-shrink: 0;
        color: currentColor;
    }

    &__figure {
        position: relative;
        z-index: 1;
        margin-bottom: clamp(48px, 7vw, 120px);
        max-width: min(480px, 72vw);
        width: 100%;
    }

    &__figure-img {
        display: block;
        width: 100%;
        height: auto;
    }

    &__stats {
        position: relative;
        z-index: 1;
        align-items: flex-start;
    }

    &__stat {
        display: flex;
        flex-direction: column;
        align-items: center;
        text-align: center;
        max-width: 370px;

        @media (min-width: 768px) {
            &--1 {
                align-items: flex-start;
                text-align: left;
                margin-right: auto;
            }

            &--2 {
                margin-left: auto;
                margin-right: auto;
                margin-top: clamp(48px, 9vw, 160px);
            }

            &--3 {
                align-items: flex-end;
                text-align: right;
                margin-left: auto;
                margin-top: clamp(96px, 16vw, 280px);
            }
        }
    }

    &__stat-value {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(64px, 10vw, 124px);
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__stat-label {
        margin-top: clamp(8px, 1.2vw, 16px);
        max-width: 284px;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(18px, 1.6vw, 24px);
        line-height: 1.25;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }
}