@use '../../utils' as *;

/* Home 12 / Section 8 — FAQ accordion */
.sec-8-home-12 {
    background-color: var(--at-neutral-50);
    padding-top: 120px;
    padding-bottom: 120px;
}

/* ── Section header ─────────────────────────────── */
.sec-8-home-12__header {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    row-gap: 16px;
    margin-bottom: 64px;
}

.sec-8-home-12__eyebrow {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.96px;
    color: var(--at-neutral-500);
    text-transform: uppercase;
}

.sec-8-home-12__title {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(36px, 5vw, 64px);
    line-height: 1.125;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
}

/* ── List ───────────────────────────────────────── */
.sec-8-home-12__list {
    display: flex;
    flex-direction: column;
    row-gap: 12px;
    max-width: 800px;
    margin-inline: auto;
}

/* ── Accordion item (native <details>) ──────────── */
.sec-8-home-12__item {
    background-color: var(--at-neutral-0);
    border: 1px solid var(--at-neutral-100);
    border-radius: 16px;
    overflow: hidden;
    transition: border-color 0.3s ease;

    &[open] {
        border-color: var(--at-neutral-300);
    }
}

.sec-8-home-12__summary {
    list-style: none;
    cursor: pointer;
    padding: 22px 24px 22px 28px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    column-gap: 16px;
    user-select: none;

    &::-webkit-details-marker {
        display: none;
    }

    &::marker {
        content: '';
    }
}

.sec-8-home-12__question {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 17px;
    line-height: 1.3;
    letter-spacing: -0.02em;
    color: var(--at-neutral-950);
}

.sec-8-home-12__toggle {
    flex-shrink: 0;
    position: relative;
    width: 32px;
    height: 32px;
    border-radius: 999px;
    background-color: var(--at-neutral-50);
    color: var(--at-neutral-950);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.3s ease, color 0.3s ease;
}

.sec-8-home-12__bar {
    position: absolute;
    background-color: currentColor;
    border-radius: 1px;
    transition: opacity 0.25s ease, transform 0.25s ease;
}

.sec-8-home-12__bar--h {
    width: 14px;
    height: 1.6px;
}

.sec-8-home-12__bar--v {
    width: 1.6px;
    height: 14px;
}

.sec-8-home-12__item[open] .sec-8-home-12__toggle {
    background-color: var(--at-neutral-950);
    color: var(--at-neutral-0);
}

.sec-8-home-12__item[open] .sec-8-home-12__bar--v {
    opacity: 0;
    transform: scaleY(0);
}

.sec-8-home-12__answer {
    padding: 0 24px 22px 28px;
    display: flex;
    flex-direction: column;
    row-gap: 16px;

    p {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.5;
        letter-spacing: -0.02em;
        color: var(--at-neutral-500);
    }
}

.sec-8-home-12__divider {
    display: block;
    width: 100%;
    height: 1px;
    background-color: var(--at-neutral-100);
    margin-top: -2px;
}

/* ── Responsive ─────────────────────────────────── */
@media #{$xxl} {
    .sec-8-home-12 {
        padding-top: 100px;
        padding-bottom: 100px;
    }
}

@media #{$xl} {
    .sec-8-home-12 {
        padding-top: 90px;
        padding-bottom: 90px;
    }
}

@media #{$lg} {
    .sec-8-home-12 {
        padding-top: 80px;
        padding-bottom: 80px;
    }
    .sec-8-home-12__header {
        margin-bottom: 48px;
    }
}

@media #{$md} {
    .sec-8-home-12 {
        padding-top: 64px;
        padding-bottom: 64px;
    }
    .sec-8-home-12__header {
        margin-bottom: 40px;
    }
    .sec-8-home-12__summary {
        padding: 20px 22px 20px 24px;
    }
    .sec-8-home-12__answer {
        padding: 0 22px 20px 24px;
    }
    .sec-8-home-12__question {
        font-size: 16px;
    }
}

@media #{$sm} {
    .sec-8-home-12 {
        padding-top: 56px;
        padding-bottom: 56px;
    }
    .sec-8-home-12__header {
        margin-bottom: 32px;
        row-gap: 12px;
    }
    .sec-8-home-12__list {
        row-gap: 10px;
    }
    .sec-8-home-12__summary {
        padding: 18px 20px 18px 22px;
        column-gap: 12px;
    }
    .sec-8-home-12__answer {
        padding: 0 20px 20px 22px;
        row-gap: 14px;

        p {
            font-size: 15px;
        }
    }
    .sec-8-home-12__question {
        font-size: 15px;
        line-height: 1.35;
    }
    .sec-8-home-12__toggle {
        width: 28px;
        height: 28px;
    }
    .sec-8-home-12__bar--h {
        width: 12px;
    }
    .sec-8-home-12__bar--v {
        height: 12px;
    }
}

@media #{$xs} {
    .sec-8-home-12 {
        padding-top: 48px;
        padding-bottom: 48px;
    }
    .sec-8-home-12__header {
        margin-bottom: 28px;
    }
    .sec-8-home-12__list {
        row-gap: 8px;
    }
    .sec-8-home-12__item {
        border-radius: 14px;
    }
    .sec-8-home-12__summary {
        padding: 16px 18px 16px 20px;
        column-gap: 12px;
    }
    .sec-8-home-12__answer {
        padding: 0 18px 18px 20px;
        row-gap: 12px;

        p {
            font-size: 14.5px;
        }
    }
    .sec-8-home-12__question {
        font-size: 14.5px;
        line-height: 1.4;
    }
    .sec-8-home-12__toggle {
        width: 26px;
        height: 26px;
    }
    .sec-8-home-12__bar--h {
        width: 11px;
    }
    .sec-8-home-12__bar--v {
        height: 11px;
    }
}
