@use '../../utils' as *;

/* Home 13 / Section 8 — The Orisa Distinction */
.sec-8-home-13 {
    background-color: var(--at-neutral-50);
    padding: 120px 96px;
}

.sec-8-home-13__inner {
    display: flex;
    flex-direction: column;
    gap: 80px;
}

/* ── Top wrapper ─────────────────────────────── */
.sec-8-home-13__top {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 32px;
}

.sec-8-home-13__head {
    display: flex;
    flex-direction: column;
    gap: 16px;
    max-width: 1100px;
}

.sec-8-home-13__tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    line-height: 1.2;
    letter-spacing: -0.05em;
    color: var(--at-neutral-900);
    text-decoration: none;
    transition: color 0.3s ease;

    &:hover,
    &:focus-visible {
        color: var(--at-theme-primary);
    }

    svg {
        transition: transform 0.3s ease;
    }

    &:hover svg,
    &:focus-visible svg {
        transform: translate(2px, -2px);
    }
}

.sec-8-home-13__title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(40px, 5vw, 72px);
    line-height: 1.111;
    letter-spacing: -0.03em;
    color: var(--at-neutral-950);
}

.sec-8-home-13__cta {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    height: 50px;
    padding: 14px 27px;
    background-color: var(--at-neutral-900);
    color: var(--at-neutral-0);
    border-radius: 50px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    letter-spacing: -0.05em;
    text-decoration: none;
    flex-shrink: 0;
    transition: opacity 0.3s ease;

    &:hover,
    &:focus-visible {
        color: var(--at-neutral-0);
        opacity: 0.9;
    }

    svg {
        transition: transform 0.3s ease;
    }

    &:hover svg,
    &:focus-visible svg {
        transform: translate(2px, -2px);
    }
}

/* ── Body ────────────────────────────────────── */
.sec-8-home-13__body {
    display: grid;
    grid-template-columns: 620px 1fr;
    gap: 64px;
    align-items: start;
}

/* ── Left ────────────────────────────────────── */
.sec-8-home-13__left {
    display: flex;
    flex-direction: column;
    gap: 32px;
}

.sec-8-home-13__media {
    width: 100%;
    overflow: hidden;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: opacity 0.3s cubic-bezier(0.22, 0.61, 0.36, 1);
    }

    &.is-changing img {
        opacity: 0;
    }
}

.sec-8-home-13__lede {
    font-family: var(--at-ff-body);
    font-weight: 500;
    font-size: 22px;
    line-height: 1.45;
    letter-spacing: -0.02em;
    color: var(--at-neutral-950);
    transition: opacity 0.3s cubic-bezier(0.22, 0.61, 0.36, 1);

    &.is-changing {
        opacity: 0;
    }
}

/* ── List ────────────────────────────────────── */
.sec-8-home-13__list {
    display: flex;
    flex-direction: column;
    padding: 0;
    margin: 0;
    border-top: 1px solid var(--at-neutral-100);
}

.sec-8-home-13__item {
    border-bottom: 1px solid var(--at-neutral-100);
    transition: border-color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1);
}

.sec-8-home-13__row {
    display: grid;
    grid-template-columns: 100px 1fr auto;
    gap: 32px;
    align-items: center;
    padding: 28px 8px;
    text-decoration: none;
    transition: background-color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1);
}

.sec-8-home-13__row-num {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 32px;
    line-height: 1;
    letter-spacing: -0.03em;
    color: var(--at-neutral-950);
    transition: color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1);
}

.sec-8-home-13__row-name {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 28px;
    line-height: 1;
    letter-spacing: -0.03em;
    color: var(--at-neutral-950);
    transition: color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
        font-size 0.5s cubic-bezier(0.22, 0.61, 0.36, 1);
}

.sec-8-home-13__row-arrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: 1px solid var(--at-neutral-300);
    color: var(--at-neutral-950);
    background-color: transparent;
    flex-shrink: 0;
    transition: background-color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
        border-color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
        color 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
        width 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
        height 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
        transform 0.55s cubic-bezier(0.34, 1.56, 0.64, 1);

    svg {
        transition: width 0.5s cubic-bezier(0.22, 0.61, 0.36, 1),
            height 0.5s cubic-bezier(0.22, 0.61, 0.36, 1);
    }
}

/* Active / hover state */
.sec-8-home-13__item--active .sec-8-home-13__row,
.sec-8-home-13__row:hover,
.sec-8-home-13__row:focus-visible {
    .sec-8-home-13__row-name {
        font-size: 36px;
    }

    .sec-8-home-13__row-arrow {
        width: 56px;
        height: 56px;
        background-color: var(--at-theme-primary);
        border-color: var(--at-theme-primary);
        color: var(--at-common-white);

        svg {
            width: 22px;
            height: 22px;
        }
    }
}

.sec-8-home-13__row:hover .sec-8-home-13__row-arrow,
.sec-8-home-13__row:focus-visible .sec-8-home-13__row-arrow {
    transform: rotate(-12deg);
}

/* ── Responsive ──────────────────────────────── */
@media #{$xxl} {
    .sec-8-home-13 {
        padding: 96px 32px;
    }

    .sec-8-home-13__body {
        grid-template-columns: 480px 1fr;
        gap: 48px;
    }

    .sec-8-home-13__media {
        height: 420px;
    }

    .sec-8-home-13__row-name {
        font-size: 22px;
    }

    .sec-8-home-13__item--active .sec-8-home-13__row .sec-8-home-13__row-name,
    .sec-8-home-13__row:hover .sec-8-home-13__row-name {
        font-size: 28px;
    }
}

@media #{$xl} {
    .sec-8-home-13 {
        padding: 80px 24px;
    }

    .sec-8-home-13__inner {
        gap: 56px;
    }

    .sec-8-home-13__body {
        grid-template-columns: 380px 1fr;
        gap: 32px;
    }

    .sec-8-home-13__media {
        height: 360px;
    }

    .sec-8-home-13__lede {
        font-size: 18px;
    }

    .sec-8-home-13__row {
        grid-template-columns: 80px 1fr auto;
        gap: 16px;
        padding: 20px 8px;
    }

    .sec-8-home-13__row-num {
        font-size: 24px;
    }

    .sec-8-home-13__row-name {
        font-size: 18px;
    }

    .sec-8-home-13__item--active .sec-8-home-13__row .sec-8-home-13__row-name,
    .sec-8-home-13__row:hover .sec-8-home-13__row-name {
        font-size: 22px;
    }
}

/* Stack body as flex column on tablet & phone */
@media (max-width: 1199.98px) {
    .sec-8-home-13__body {
        display: flex;
        flex-direction: column;
    }
}

@media #{$lg} {
    .sec-8-home-13 {
        padding: 64px 20px;
    }

    .sec-8-home-13__top {
        flex-direction: column;
        align-items: flex-start;
        gap: 24px;
    }

    .sec-8-home-13__body {
        gap: 32px;
    }

    .sec-8-home-13__media {
        height: 380px;
    }
}

@media #{$md} {
    .sec-8-home-13 {
        padding: 48px 30px;
    }

    .sec-8-home-13__inner {
        gap: 40px;
    }

    .sec-8-home-13__media {
        height: 320px;
    }

    .sec-8-home-13__row-arrow {
        width: 36px;
        height: 36px;
    }

    .sec-8-home-13__item--active .sec-8-home-13__row .sec-8-home-13__row-arrow,
    .sec-8-home-13__row:hover .sec-8-home-13__row-arrow {
        width: 44px;
        height: 44px;
    }
}

@media #{$sm} {
    .sec-8-home-13 {
        padding: 36px 30px;
    }

    .sec-8-home-13__media {
        height: 260px;
    }

    .sec-8-home-13__row {
        grid-template-columns: 60px 1fr auto;
        padding: 16px 4px;
    }

    .sec-8-home-13__row-num {
        font-size: 20px;
    }

    .sec-8-home-13__row-name {
        font-size: 16px;
    }
}

@media #{$xs} {
    .sec-8-home-13 {
        padding: 36px 30px;
    }

    .sec-8-home-13__title {
        font-size: 32px;
    }

    .sec-8-home-13__lede {
        font-size: 16px;
    }

    .sec-8-home-13__row-name {
        font-size: 14px;
    }
}

/* Cascading mobile pivot: stack top wrapper for tablet & phone */
@media (max-width: 1199.98px) {
    .sec-8-home-13__top {
        flex-direction: column;
        align-items: flex-start;
        gap: 24px;
    }
}

/* Cascading mobile pivot: shrink row grid for small phones */
@media (max-width: 574.98px) {
    .sec-8-home-13__row {
        grid-template-columns: 56px 1fr auto;
        gap: 12px;
        padding: 16px 4px;
    }

    .sec-8-home-13__row-num {
        font-size: 18px;
    }
}