@use '../../utils' as *;

/* ===========================================================
   Section 1 — Home 15 (Agency Hero)
   =========================================================== */

.sec-1-home-15 {
    padding-top: 66px;
    padding-bottom: 80px;
    background-color: var(--at-neutral-0);

    @media #{$lg},
    #{$md} {
        padding-top: 60px;
        padding-bottom: 56px;
    }

    @media #{$sm},
    #{$xs} {
        padding-top: 60px;
        padding-bottom: 40px;
    }

    /* ---- Hero card ---- */
    &__card {
        position: relative;
        width: 100%;
        height: 637px;
        max-height: calc(100vh - 160px);
        overflow: hidden;
        border-radius: 16px;
        background-color: var(--at-neutral-900);
        isolation: isolate;

        @media #{$xl} {
            height: 560px;
        }

        @media #{$lg} {
            height: 520px;
        }

        @media #{$md} {
            height: 480px;
        }

        @media #{$sm} {
            height: 560px;
            max-height: none;
        }

        @media #{$xs} {
            height: 520px;
            max-height: none;
            border-radius: 12px;
        }
    }

    &__bg {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        z-index: 1;
        pointer-events: none;
    }

    &__grid {
        position: absolute;
        inset: 0;
        z-index: 2;
        pointer-events: none;
        background-repeat: no-repeat;
        background-position: center center;
        background-size: 80% auto;
        opacity: 0.5;
        mix-blend-mode: screen;

        @media #{$md},
        #{$sm},
        #{$xs} {
            opacity: 0.35;
            background-size: 130% auto;
        }
    }

    /* ---- Top row (coordinates + email) ---- */
    &__top {
        position: absolute;
        top: 30px;
        left: 35px;
        right: 35px;
        z-index: 4;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        color: var(--at-common-white);

        @media #{$sm},
        #{$xs} {
            top: 20px;
            left: 20px;
            right: 20px;
        }
    }

    &__coord {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-common-white);

        @media #{$sm},
        #{$xs} {
            font-size: 12px;
            gap: 6px;
        }
    }

    &__coord-icon {
        flex-shrink: 0;
        width: 20px;
        height: 20px;

        @media #{$sm},
        #{$xs} {
            width: 16px;
            height: 16px;
        }
    }

    &__email {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-common-white);
        text-decoration: none;
        transition: opacity 0.3s ease;

        &:hover,
        &:focus-visible {
            color: var(--at-common-white);
            opacity: 0.7;
        }

        @media #{$sm},
        #{$xs} {
            font-size: 12px;
        }
    }

    /* ---- Scroll indicator (right side, mid-height) ---- */
    &__scroll {
        position: absolute;
        right: 40px;
        top: 50%;
        z-index: 4;
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 18px;
        transform: translateY(-50%);
        color: var(--at-neutral-100);

        @media #{$md},
        #{$sm},
        #{$xs} {
            display: none;
        }
    }

    &__scroll-line {
        display: block;
        width: 1px;
        height: 70px;
        background-color: #fff;
        opacity: 0.7;
        animation: secOneHome15ScrollLine 2.4s ease-in-out infinite;
    }

    &__scroll-label {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 12px;
        line-height: 1;
        letter-spacing: 0.05em;
        text-transform: uppercase;
        writing-mode: vertical-rl;
        transform: rotate(180deg);
    }

    @keyframes secOneHome15ScrollLine {

        0%,
        100% {
            transform: scaleY(0.4);
            transform-origin: top;
            opacity: 0.4;
        }

        50% {
            transform: scaleY(1);
            transform-origin: top;
            opacity: 0.9;
        }
    }

    /* ---- Bottom row (tags + clients) ---- */
    &__bottom {
        position: absolute;
        left: 35px;
        right: 35px;
        bottom: 40px;
        z-index: 4;
        display: flex;
        align-items: flex-end;
        justify-content: space-between;
        gap: 32px;

        @media #{$md} {
            flex-direction: column;
            align-items: flex-start;
            gap: 20px;
        }

        @media #{$sm},
        #{$xs} {
            left: 20px;
            right: 20px;
            bottom: 24px;
            flex-direction: column;
            align-items: flex-start;
            gap: 18px;
        }
    }

    &__tags {
        display: flex;
        flex-wrap: wrap;
        gap: 12px;
        max-width: 540px;
        padding: 0;
        margin: 0;
        list-style: none;

        @media #{$md},
        #{$sm},
        #{$xs} {
            max-width: none;
        }
    }

    &__tag {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        padding: 15px 19px;
        background-color: rgba(70, 70, 70, 0.2);
        border: 1px solid rgba(255, 255, 255, 0.3);
        border-radius: 32px;
        backdrop-filter: blur(24px);
        -webkit-backdrop-filter: blur(24px);
        color: #fff;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.02em;
        white-space: nowrap;

        svg {
            flex-shrink: 0;
        }

        @media #{$sm},
        #{$xs} {
            padding: 11px 14px;
            font-size: 13px;
            gap: 8px;
        }
    }

    &__clients {
        display: flex;
        flex-direction: column;
        align-items: flex-end;
        gap: 15px;
        color: var(--at-common-white);

        @media #{$md},
        #{$sm},
        #{$xs} {
            align-items: flex-start;
        }
    }

    &__avatars {
        display: inline-flex;
        align-items: center;
    }

    &__avatar {
        width: 34px;
        height: 34px;
        border-radius: 50%;
        border: 2px solid var(--at-common-white);
        object-fit: cover;
        background-color: var(--at-neutral-700);

        &+& {
            margin-left: -12px;
        }
    }

    &__clients-text {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.25;
        letter-spacing: -0.02em;
        text-align: right;
        color: var(--at-common-white);

        @media #{$md},
        #{$sm},
        #{$xs} {
            text-align: left;

            br {
                display: none;
            }
        }

        @media #{$xs} {
            font-size: 14px;
        }
    }

    /* ---- Title block under the hero card ---- */
    &__title-block {
        position: relative;
        padding-top: 44px;

        @media #{$xl} {
            padding-top: 36px;
        }

        @media #{$lg},
        #{$md} {
            padding-top: 28px;
        }

        @media #{$sm},
        #{$xs} {
            padding-top: 22px;
        }
    }

    &__title {
        font-family: var(--at-ff-heading);
        font-weight: 700;
        font-size: 173px;
        line-height: 1;
        letter-spacing: -0.05em;
        text-align: center;
        color: var(--at-neutral-900);
        margin: 0;

        @media #{$x4l},
        #{$x3l} {
            font-size: 150px;
        }

        @media #{$xxl} {
            font-size: 128px;
        }

        @media #{$xl} {
            font-size: 110px;
        }

        @media #{$lg} {
            font-size: 92px;
        }

        @media #{$md} {
            font-size: 72px;
        }

        @media #{$sm} {
            font-size: 56px;
        }

        @media #{$xs} {
            font-size: 40px;
        }
    }

    &__title-meta {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 16px;
        margin-top: -22px;

        @media #{$xl} {
            margin-top: -16px;
        }

        @media #{$lg},
        #{$md} {
            margin-top: -10px;
        }

        @media #{$sm} {
            margin-top: 8px;
        }

        @media #{$xs} {
            margin-top: 10px;
            flex-wrap: wrap;
            gap: 8px;
        }
    }

    &__title-side {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.4;
        letter-spacing: -0.02em;
        text-decoration: underline;
        text-underline-offset: 3px;
        color: var(--at-neutral-900);

        @media #{$xs} {
            font-size: 13px;
        }
    }
}