@use '../../utils' as *;

/* Home 12 / Section 6 — About + Brand logos (dark) */
.sec-6-home-12 {
    background-color: #0f0f0f;
    color: var(--at-common-white);
    padding-bottom: 100px;
    padding-top: 32px;
    overflow: hidden;
}

/* ── Top bar with line ──────────────────────────── */
.sec-6-home-12__topbar {
    position: relative;
    margin-bottom: 0;
}

.sec-6-home-12__topline {
    display: block;
    width: 100%;
    height: 1px;
    background-color: rgba(255, 255, 255, 0.18);
    margin-bottom: 24px;
}

.sec-6-home-12__topbar-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    column-gap: 24px;
}

.sec-6-home-12__topbar-label {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 14px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--at-neutral-0);
    white-space: nowrap;
}

/* ── Lede paragraph ─────────────────────────────── */
.sec-6-home-12__lede-wrap {
    padding: 96px 0;
}

.sec-6-home-12__lede {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: clamp(24px, 3.5vw, 64px);
    line-height: 1.18;
    letter-spacing: -0.03em;
    color: var(--at-neutral-0);
    max-width: 100%;
}

/* ── Brand logos — Swiper marquee ────────────────── */
.sec-6-home-12__brands-strip {
    position: relative;
    overflow: hidden;
    padding-inline: 24px;
    color: var(--at-neutral-0);
}

.sec-6-home-12-slider {
    overflow: visible;

    .swiper-wrapper {
        /* Linear timing for continuous marquee feel */
        transition-timing-function: linear !important;
        align-items: center;
    }
}

.sec-6-home-12__brand-slide {
    flex-shrink: 0;
    display: flex !important;
    align-items: center;
    justify-content: center;
    height: 64px;
}

.sec-6-home-12__brand-img {
    display: inline-block;
    height: 40px;
    width: auto;
    max-width: 100%;
    object-fit: contain;
    filter: brightness(0) invert(1);
    opacity: 0.95;
}

.sec-6-home-12__brand {
    display: inline-flex;
    align-items: center;
    column-gap: 8px;
    color: var(--at-neutral-0);
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 22px;
    line-height: 1;
    letter-spacing: -0.04em;
}

.sec-6-home-12__brand-mark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    color: var(--at-neutral-0);
}

.sec-6-home-12__brand-name {
    color: var(--at-neutral-0);
}

.sec-6-home-12__brand-name--logo {
    font-size: 24px;
    margin-right: 2px;
}

.sec-6-home-12__brand-loop {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    border: 2px solid var(--at-neutral-0);
    margin-right: 1px;

    &+& {
        margin-left: -7px;
    }
}

.sec-6-home-12__brand-name--oslo {
    display: inline-flex;
    align-items: baseline;
    font-weight: 600;
    font-size: 26px;
    letter-spacing: -0.04em;
}

.sec-6-home-12__brand-dot {
    color: var(--at-theme-primary);
    font-size: 1em;
}

/* ── Responsive ─────────────────────────────────── */
@media #{$xxl} {
    .sec-6-home-12__lede-wrap {
        padding: 80px 0;
    }
}

@media #{$xl} {
    .sec-6-home-12__lede-wrap {
        padding: 72px 0;
    }
    .sec-6-home-12__brand-slide {
        height: 56px;
    }
    .sec-6-home-12__brand-img {
        height: 36px;
    }
}

@media #{$lg} {
    .sec-6-home-12 {
        padding-bottom: 80px;
    }
    .sec-6-home-12__lede-wrap {
        padding: 56px 0;
    }
    .sec-6-home-12__brand-slide {
        height: 52px;
    }
    .sec-6-home-12__brand-img {
        height: 32px;
    }
    .sec-6-home-12__brand {
        font-size: 20px;
    }
}

@media #{$md} {
    .sec-6-home-12 {
        padding-bottom: 64px;
    }
    .sec-6-home-12__lede-wrap {
        padding: 48px 0;
    }
    .sec-6-home-12__brand-slide {
        height: 48px;
    }
    .sec-6-home-12__brand-img {
        height: 28px;
    }
    .sec-6-home-12__brand {
        font-size: 18px;
    }
}

@media #{$sm} {
    .sec-6-home-12 {
        padding-bottom: 56px;
    }
    .sec-6-home-12__topline {
        margin-bottom: 18px;
    }
    .sec-6-home-12__lede-wrap {
        padding: 36px 0;
    }
    .sec-6-home-12__brand-slide {
        height: 44px;
    }
    .sec-6-home-12__brand-img {
        height: 24px;
    }
    .sec-6-home-12__brand {
        font-size: 17px;
    }
    .sec-6-home-12__topbar-label {
        font-size: 13px;
    }
}

@media #{$xs} {
    .sec-6-home-12 {
        padding-bottom: 48px;
        padding-top: 24px;
    }
    .sec-6-home-12__topline {
        margin-bottom: 14px;
    }
    .sec-6-home-12__lede-wrap {
        padding: 28px 0;
    }
    .sec-6-home-12__lede {
        font-size: 22px;
        line-height: 1.25;
    }
    .sec-6-home-12__brand-slide {
        height: 40px;
    }
    .sec-6-home-12__brand-img {
        height: 22px;
    }
    .sec-6-home-12__brand {
        font-size: 16px;
    }
    .sec-6-home-12__topbar-label {
        font-size: 12px;
    }
}
