@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-6-home-15 (Home 15 — Meet our team + throwable logos)
/*----------------------------------------*/

.sec-6-home-15 {
    position: relative;
    padding-top: clamp(48px, 6vw, 100px);
    padding-bottom: clamp(56px, 8vw, 140px);
    background: var(--at-neutral-0, #fefefe);
    overflow: hidden;

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__layout {
        display: flex;
        flex-direction: column;
        gap: clamp(28px, 4vw, 40px);

        @media (min-width: 1200px) {
            display: grid;
            grid-template-columns: minmax(0, 1fr) minmax(220px, min(28vw, 407px)) minmax(0, 1fr);
            grid-template-rows: auto auto auto;
            gap: clamp(6px, 0.8vw, 10px);
            align-items: start;
        }
    }

    &__title-block {
        text-align: center;

        @media (min-width: 1200px) {
            grid-column: 2;
            grid-row: 1 / span 2;
            align-self: center;
            justify-self: center;
            z-index: 2;
            max-width: min(765px, 100%);
            padding: clamp(16px, 3vw, 48px) 0;
            pointer-events: none;

            .sec-6-home-15__eyebrow,
            .sec-6-home-15__title {
                pointer-events: auto;
            }
        }
    }

    &__eyebrow {
        img {
            width: 14px;
            height: 13px;
        }
    }

    &__eyebrow-text {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__title {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(40px, 6vw, 84px);
        line-height: 0.95;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950, #0f0f0f);
        text-wrap: balance;
    }

    &__member {
        min-width: 0;
        backface-visibility: hidden;
        transform-style: preserve-3d;

        @media (min-width: 1200px) {
            max-width: 407px;

            &--1 {
                grid-column: 1;
                grid-row: 1;
                justify-self: start;
            }

            &--2 {
                grid-column: 3;
                grid-row: 1;
                justify-self: end;
                margin-top: 0;
            }

            &--3 {
                grid-column: 1;
                grid-row: 2;
                justify-self: start;
                margin-top: 0;
            }

            &--4 {
                grid-column: 3;
                grid-row: 2;
                justify-self: end;
                margin-top: clamp(4px, 1vw, 14px);
            }
        }
    }

    &__member-link {
        display: block;
        color: inherit;
        text-decoration: none;
        transition: opacity 0.3s ease;

        &:hover {
            opacity: 0.92;
        }
    }

    &__member-frame {
        position: relative;
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-100, #dfdfdf);
        aspect-ratio: 407 / 550;
    }

    &__member-img {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center top;
    }

    &__member-overlay {
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        min-height: 34.5%;
        padding: clamp(28px, 3vw, 40px) clamp(24px, 3.5vw, 46px);
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
        background: linear-gradient(180deg, rgba(26, 26, 26, 0) 11.9%, rgba(26, 26, 26, 0.92) 100%);
        backdrop-filter: blur(3px);
        pointer-events: none;
    }

    &__member-name {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(26px, 2.2vw, 32px);
        line-height: 1.1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0, #fefefe);
    }

    &__member-role {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(18px, 1.4vw, 22px);
        line-height: 1.2;
        letter-spacing: -0.02em;
        color: var(--at-neutral-0, #fefefe);
        opacity: 0.8;
    }

    &__member-fab {
        position: absolute;
        top: clamp(20px, 2vw, 26px);
        right: clamp(20px, 2vw, 26px);
        z-index: 2;
        width: 40px;
        height: 40px;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        pointer-events: none;

        &--light {
            background: var(--at-neutral-0, #fefefe);
            color: var(--at-neutral-900, #1d1d1d);
        }

        &--dark {
            background: var(--at-neutral-900, #1d1d1d);
            color: var(--at-neutral-0, #fefefe);
        }
    }

    &__foot {
        @media (min-width: 1200px) {
            grid-column: 2 / -1;
            grid-row: 3;
            justify-self: end;
            max-width: min(775px, 100%);
            text-align: left;
        }
    }

    &__foot-text {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(22px, 2.2vw, 36px);
        line-height: 1.2;
        letter-spacing: -0.05em;
        text-transform: capitalize;
        color: var(--at-neutral-700, #303030);
    }

    &__cta {
        height: 50px;
        padding: 14px 27px;
        border-radius: 50px;
        background: var(--at-neutral-900, #1d1d1d);
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0, #fefefe) !important;
        text-decoration: none !important;
        white-space: nowrap;
        transition: background 0.25s ease, color 0.25s ease;

        &:hover {
            background: var(--at-theme-primary);
            color: var(--at-neutral-0) !important;
        }
    }

    &__cta-arrow {
        flex-shrink: 0;
        color: currentColor;
    }

    /* --- Throwable logos scene (scoped layout; physics from throwable.js) --- */
    &__throw {
        margin-top: 0;
        position: absolute;
        bottom: 0;
        height: 600px;
        z-index: 1;
        width: 100%;

        .client-capsule-wrapper {
            margin-top: 0;
            height: 380px;

            @media (min-width: 768px) {
                height: 460px;
            }

            @media (min-width: 992px) {
                height: 520px;
            }

            @media (min-width: 1400px) {
                height: 580px;
            }
        }

        .client-box--brand-h15 {
            background-color: var(--at-theme-primary);
        }
    }
}