@use '../../utils' as *;

/*----------------------------------------*/
/*  Home 8 — Section 2 (Orange marquee — carouselTicker-left)
/*  Brand-1 bar, 32px semibold white, 20px gap, 16px star
/*----------------------------------------*/

.sec-2-home-8 {
    overflow: hidden;

    &__row {
        position: relative;
        width: 100%;
        overflow: hidden;
    }

    &__ticker {
        background-color: var(--at-theme-primary);
    }

    &__list {
        gap: 20px !important;
        white-space: nowrap;

        @media #{$md,$sm,$xs} {
            gap: 16px !important;
        }
    }

    &__item {
        font-family: var(--at-heading-font);
        font-size: 32px;
        font-weight: 600;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0);
        flex-shrink: 0;

        @media #{$md} {
            font-size: 26px;
        }

        @media #{$sm,$xs} {
            font-size: 20px;
        }
    }

    &__sep {
        flex-shrink: 0;
        width: 16px;
        height: 16px;
        flex: 0 0 16px;
        display: inline-flex;
        align-items: center;
        justify-content: center;

        img {
            width: 100%;
            height: 100%;
            display: block;
            object-fit: contain;
        }

        @media #{$sm,$xs} {
            width: 14px;
            height: 14px;
            flex-basis: 14px;
        }
    }

    // Ruled accent strip (~28px) — thin orange lines on page background
    &__rules {
        height: 28px;
        width: 100%;
        background-color: var(--at-neutral-0);
        background-image: linear-gradient(to bottom,
                var(--at-theme-primary) 0,
                var(--at-theme-primary) 1px,
                transparent 1px,
                transparent 6px,
                var(--at-theme-primary) 6px,
                var(--at-theme-primary) 7px,
                transparent 7px,
                transparent 11px,
                var(--at-theme-primary) 11px,
                var(--at-theme-primary) 12px,
                transparent 12px,
                transparent 15px,
                var(--at-theme-primary) 15px,
                var(--at-theme-primary) 16px,
                transparent 16px,
                transparent 19px,
                var(--at-theme-primary) 19px,
                var(--at-theme-primary) 20px,
                transparent 20px);
    }
}